// Proposed PDR verification planning. Nothing here records a completed test,
// assigns a supplier qualification, or changes the engineering mass ledger.
import {flightKnowledgeSources} from './part-knowledge-flight.js';
import {materialKnowledgeSources} from './part-knowledge-materials.js';
import {groundKnowledgeSources} from './part-knowledge-ground.js';
import {launchKnowledgeSources} from './part-knowledge-launch.js';
import {electricalSources} from './electrical-architecture.js';
import {buildElectricalProgram,electricalProgramForItem} from './electrical-program.js';

const GEVS='https://standards.nasa.gov/system/files/tmp/GSFC-STD-7000B_Approved_Admn%20Ext.pdf';
const ref=(title,url,section,description,organization='NASA')=>({title,url,section,description,organization});
export const verificationSources=Object.freeze({
 ...flightKnowledgeSources,...materialKnowledgeSources,...groundKnowledgeSources,...launchKnowledgeSources,
 ...Object.fromEntries(Object.entries(electricalSources).filter(([,s])=>s.url).map(([id,s])=>[id,{...s,organization:s.kind==='supplier-reference'?'Supplier reference':s.kind==='standard'?'Engineering standard':'NASA'}])),
 'v-plan':ref('NASA Systems Engineering Handbook — Technical Planning','https://www.nasa.gov/reference/6-1-technical-planning/','6.1; Verification Plan','Verification planning begins with requirements, is baselined at PDR, and matures with the design.'),
 'v-methods':ref('NASA Systems Engineering Handbook — Product Verification','https://www.nasa.gov/reference/5-3-product-verification/','5.3; methods, qualification and acceptance','Explains test, analysis, inspection and demonstration; distinguishes design qualification from acceptance of each delivered article.'),
 'v-integration':ref('NASA Systems Engineering Handbook — Product Integration','https://www.nasa.gov/reference/5-2-product-integration/','5.2','Defines interface readiness, integration planning and verification of the assembled product.'),
 'v-outline':ref('NASA Systems Engineering Handbook — Verification and Validation Plan outline','https://www.nasa.gov/reference/system-engineering-handbook-appendix/','Appendix I; requirements flowdown, verification approach, end-item verification','A recursive plan structure from components through assemblies to the integrated system. The web heading says Integration Plan; the content is the V&V outline.'),
 'v-gevs':ref('GEVS — current GSFC-STD-7000B','https://standards.nasa.gov/standard/GSFC/GSFC-STD-7000','Version B; 2021, administrative extension April 2026','GSFC environmental verification guidance. Mission applicability and approved tailoring must be established; it is not a universal civil-works or supplier certification standard.'),
 'v-gevs-plan':ref('GEVS — verification planning and tailoring',GEVS,'1.2–1.3; 1.9; 1.12–1.14; 2.1.1; 2.2','Trace requirements, articles, methods, assumptions, procedures, instrument calibration, reports and anomalies.'),
 'v-gevs-function':ref('GEVS — electrical function and performance',GEVS,'2.3.1–2.3.5','Interface checks before mating; comprehensive functional baselines and selected checks around environmental exposures.'),
 'v-gevs-mechanical':ref('GEVS — structural and mechanical verification',GEVS,'2.4.1–2.4.4','Loads/model correlation, vibration, acoustic and shock verification at the appropriate article and assembly level.'),
 'v-gevs-mechanism':ref('GEVS — mechanical function',GEVS,'2.4.5; especially 2.4.5.1–2.4.5.4','Life, deployment, torque/force margin and acceptance are related but distinct demonstrations.'),
 'v-gevs-mass':ref('GEVS — mass properties',GEVS,'2.4.7','Mass, center of gravity and inertia verification and the importance of configuration and fixture accounting.'),
 'v-gevs-emc':ref('GEVS — electromagnetic compatibility',GEVS,'2.5.1–2.5.3','Project EMC control and test plans, representative harnessing, source impedance, emissions and susceptibility.'),
 'v-gevs-tvac':ref('GEVS — thermal-vacuum verification',GEVS,'2.6.2–2.6.3','Derive chamber conditions and instrumentation from allowable flight temperatures and the selected verification approach.'),
 'v-gevs-balance':ref('GEVS — thermal balance and model correlation',GEVS,'2.6.4','Simulated hot, cold and survival cases exercise thermal control and provide measured data for model correlation.'),
 'v-gevs-clean':ref('GEVS — contamination, coatings and leakage',GEVS,'2.6.5–2.6.6; 2.8.1–2.8.2','Manage surface cleanliness, molecular contamination, coatings evidence and verified fluid-system integrity.'),
});

export const verificationSettings=Object.freeze(Object.fromEntries([
 ['studio','Isolated','Inspect the modeled item without a surrounding facility.'],
 ['installed','Installed','Show the item in its surrounding assembly and its real modeled interfaces.'],
 ['review','Integration review','A size-appropriate bench or stand for receiving inspection and review.'],
 ['vibration','Vibration','Instrumented shaker and fixture; input spectrum, axes and limits require an approved plan.'],
 ['thermal-vacuum','Thermal vacuum','Schematic cutaway of a sealed test volume. Use thermal engineering to define boundaries and predict the article response.'],
 ['thermal-cycle','Thermal cycling','Atmospheric boundary for compatible articles, coupons or ground equipment. Define the article, ramp, dwell and acceptance criteria in thermal engineering.'],
 ['acoustic','Acoustic','Reverberant test setting for large exposed panels, fairings or payload-level testing.'],
 ['rf-chamber','RF / EMC chamber','Absorber-lined setting for antenna, electromagnetic compatibility and calibrated RF work.'],
 ['optical-bench','Optical metrology','A reference optical bench for alignment, wavefront or optical-link measurements.'],
 ['load-frame','Load / proof stand','Reaction frame and load cells; all load cases and limits remain project-approved inputs.'],
 ['mass-properties','Mass properties','A weighing and balance fixture with explicit tare and coordinate references.'],
 ['pressure-bench','Pressure / fluid bench','Controlled fluid circuit for integrity, flow and pressure instrumentation.'],
 ['electrical-bench','Electrical checkout','Protected power, signal stimulus and measurement equipment.'],
 ['clean-inspection','Clean inspection','Receiving inspection, workmanship, cleanliness and process evidence.'],
 ['deployment','Deployment stand','Supported motion or gravity-offload demonstration; the animation is illustrative.'],
 ['fit-check','Fit and mate','Mating interface, access and clearance review before integration.'],
 ['propulsion-stand','Propulsion test stand','Illustrative provider-controlled propulsion test facility.'],
 ['site-commissioning','Site commissioning','Installed utilities, civil works and integrated commissioning context.'],
].map(([id,label,description])=>[id,{id,label,description}])));

const unique=a=>[...new Set(a.filter(Boolean))];
const get=(c,id)=>c?.byId?.get?.(id)||c?.byId?.[id]||c?.records?.find(r=>r.id===id);
const fact=(r,label)=>r.facts?.find(f=>f.label===label)?.value;
const finite=v=>typeof v==='number'&&Number.isFinite(v);
const pretty=(v,d=3)=>finite(v)?Number(v.toPrecision(d)):v;
const datum=(label,value,unit='',basis='Current workbench configuration; an allocation or model input, not measured hardware.')=>({label,value:finite(value)?pretty(value,5):(value==null||typeof value==='number'?'Unallocated':value),unit,basis});
const steps=(kind,labels,caption='Planned sequence; no measured response or test result is shown.')=>({kind,steps:labels.map(x=>typeof x==='string'?{label:x,description:''}:x),caption});
const standardPrereqs=['Approved requirement and verification procedure, article/configuration identification and applicable drawing revision.','Calibrated instruments, characterized fixture and measurement uncertainty appropriate to the criterion.','Review open hazards and anomalies, establish abort limits and record a baseline before applying the stimulus.'];
const standardEvidence=['Signed procedure and configuration record','Calibration and measurement-uncertainty record','Raw observations, reduced data and requirement disposition','Anomaly resolution and authorized acceptance-review record'];
function activity(id,title,methods,setting,requirement,approach,measurements,criteria,extra={}){
 return {id,title,requirement,methods,setting,objective:requirement,approach,measurements,criteria,conditions:'Levels, duration, tolerances and article selection require project approval before test readiness review.',article:'flight',evidence:standardEvidence,prerequisites:standardPrereqs,status:'planned',sources:['v-methods'],...extra};
}
function profile(id,title,summary,activities,extra={}){
 return {profile:id,title,summary,level:'Assembly',scope:'Proposed workbench PDR plan. Requirements and criteria below are planning allocations; completion, acceptance and flight qualification are not asserted.',defaultSetting:'review',settings:unique(['studio','installed','review',...activities.map(a=>a.setting)]),activities,analyses:[],sources:['v-plan','v-methods','v-outline','v-integration'],...extra};
}
function review(r){
 return activity('configuration','Configuration and receiving inspection',['inspection'],'clean-inspection',`${r.title} shall match the controlled part definition and be traceable to its build or delivery record.`,
 'Compare identity, revision, quantity, material/process records, visible workmanship and interface drawing against the receiving record. Record discrepancies before integration.',
 ['Part or lot identity','Drawing and firmware revision where applicable','Visible damage, dimensions and connector condition'],
 'Identity and supplied records agree with the approved configuration; dimensional and workmanship discrepancies are dispositioned. A rendered model or supplier brochure does not close this requirement.',{sources:['v-gevs-plan','v-methods'],chart:steps('inspection',['Identify','Inspect','Trace records','Disposition'])});
}
function environmental(r,{mechanical=true,thermal=true,emc=false}={}){
 const a=[];
 if(mechanical)a.push(activity('mechanical-environment','Launch mechanical environment',['analysis','test'],'vibration',`${r.title} shall retain structural integrity and required function after the allocated launch environment.`,
 'Use predicted interface loads and the mounted configuration to select unit/subassembly vibration, shock or higher-level acoustic coverage. Characterize the fixture, control inputs and response limits; compare pre/post functional checks. Avoid duplicate exposure when higher-level evidence supplies coverage.',
 ['Input and response acceleration','Resonant frequencies and damping where required','Fastener/connector condition','Pre/post functional change'],
 'Approved response, stress and functional limits are met with all required axes and cases covered; no unexplained structural or functional change remains. Spectrum, shock response, notching and duration are unallocated here.',{article:'qualification',sources:['v-gevs-mechanical','v-gevs-plan'],chart:steps('vibration',['Baseline','Characterize fixture','Approved axes / cases','Post-check','Evidence review'])}));
 if(thermal)a.push(activity('thermal-environment','Thermal-vacuum performance',['analysis','test'],'thermal-vacuum',`${r.title} shall meet its allocated performance through the mission thermal and vacuum envelope.`,
 'Predict the chamber setup and heat paths before testing. Measure the item at stabilized hot/cold conditions, exercise applicable operating modes and compare the final ambient baseline. Tailor qualification, protoflight and recurring acceptance exposure separately.',
 ['Article temperatures and gradients','Chamber pressure and boundary temperatures','Functional measurements at plateaus','Power and heater state when applicable'],
 'All allocated functions remain within their limits at the approved article temperatures; final performance shows no unresolved degradation. Chamber set points, cycle count, dwell and qualification margin require thermal-engineer allocation.',{article:'qualification',sources:['v-gevs-tvac','v-gevs-function'],chart:steps('thermal-cycle',['Ambient baseline','Cold plateau','Hot plateau','Repeat approved cycles','Return / recheck'])}));
 if(emc)a.push(activity('emc','Electromagnetic compatibility',['analysis','test'],'rf-chamber',`${r.title} shall not disturb adjacent systems and shall tolerate its allocated conducted and radiated environment.`,
 'Plan the relevant emissions and susceptibility methods using representative grounding, harness routing and source impedance; monitor functional behavior while applying the approved test environment.',
 ['Conducted / radiated emissions','Susceptibility stimulus at the interface','Functional error and recovery logs'],
 'Measurements meet the project EMC control plan and the item maintains specified function. Frequency ranges, limits, modulations and harness configuration remain open until the interface and EMC plan are approved.',{sources:['v-gevs-emc'],chart:steps('signal',['Source / harness','Article','Monitor function','Compare EMC allocation'])}));
 return a;
}
function baseAnalyses(r,c,h){
 const analyses=[];
 if(finite(r.extendedMassKg))analyses.push({id:'mass-allocation',title:'Allocated mass and measurement boundary',description:'The MEL value is a design allocation. Plan a tared measurement of the matching configuration and compare it with the allocated mass; rendered child details are already included.',kind:'mass',inputs:[datum('MEL allocation',r.extendedMassKg,'kg'),datum('Quantity',r.quantity??'Unallocated',r.quantityUnit||'')],outputs:[datum('Average allocation per listed unit',finite(r.quantity)&&r.quantity>0?r.extendedMassKg/r.quantity:'Unallocated','kg'),datum('Mass result','Measurement pending','', 'No as-built mass has been entered.')],equation:'Average allocation = MEL allocation / quantity',limits:['A quantity may represent an area, length or inventory rather than identical hardware units.','No independently allocated child mass or measured center of gravity is inferred.'],sources:['v-gevs-mass'],status:'study'});
 if(r.massAccounting==='included-in-parent')analyses.push({id:'parent-boundary',title:'Parent assembly and material evidence',description:'This detail inherits its mass from the parent. Coupon and process data can support the detail; installed performance remains an assembly-level obligation.',kind:'interfaces',inputs:[datum('Parent',get(c,r.parentId)?.title||r.parentId),datum('Modeled material',fact(r,'Material')||r.materialId||'Not selected')],outputs:[datum('Mass accounting','Included in parent'),datum('Verification ownership','Lot / process plus parent assembly')],limits:['Visual material appearance does not establish alloy, layup, coating thickness or supplier qualification.','Record serial/lot traceability and the assembled configuration used by each evidence item.'],sources:['v-plan','v-integration'],status:'study'});
 return analyses;
}
function integrationFor(r,c){
 const parent=get(c,r.parentId),destination=parent?.title||(r.category==='flight'?'spacecraft subsystem and vehicle':r.category==='launch'?'launch-vehicle and payload campaign':r.category==='ground'?'processing facility and supported flight interface':'launch-site integrated systems');
 if((r.category==='site'&&!/^site:(connection|umbilical)-/.test(r.id))||['ground:facility','ground:bridge-crane','ground:propellant-loading'].includes(r.id))return {parentId:parent?.id,title:`Commissioning and operational handover: ${destination}`,prerequisites:['Controlled as-built configuration, applicable design approvals and construction/installation inspections are available.','Subsystem commissioning, calibration and protective-control evidence are reviewed; open work and authority responsibilities are recorded.'],steps:['Reconcile the as-built configuration, surveyed interfaces and approved design records.','Demonstrate utility, control and vehicle/campaign interface readiness in the installed facility.','Complete the integrated commissioning scenarios and resolve interface discrepancies.','Hand over the authorized operating envelope, maintenance/inspection schedule, training and configuration records to the responsible facility operator.'],evidence:['As-built drawings, surveys and design-approval record','Subsystem and integrated commissioning reports','Open-item dispositions and operational acceptance / maintenance record']};
 return {parentId:parent?.id,title:`Release to ${destination}`,prerequisites:['Applicable lower-level verification evidence is reviewed, with concessions and open work explicitly recorded.','Mating configuration and interface requirements are compatible; required ground equipment and operators are ready.'],steps:[`Identify and protect ${r.title} during handover.`,`Inspect and mate the approved interfaces to ${destination}.`,'Perform the planned interface and integrated functional checks; resolve emergent interactions.','Update configuration and requirement traceability before authorizing the next integration step.'],evidence:['Article-specific acceptance data package','Approved interface record and integration traveler','Integrated verification results and anomaly dispositions']};
}

// Profile resolvers below add function-specific tests, measured quantities and
// live sizing studies. The generic receiving record is also a defensive fallback
// for a future catalog ID, not a claim of complete verification coverage.
const flightSpecs={
 '01.01':{purpose:'Compute useful payload work while carrying heat into the cold-plate interface.',setting:'electrical-bench',title:'Loaded compute and cold-plate characterization',requirement:'The accelerator assembly shall execute the declared workload without uncorrected errors while respecting its electrical and junction-temperature allocations.',approach:'Run a versioned workload and reference output on each accelerator path. Instrument the supply, junction sensors and cold-plate boundary; vary load and exercise error reporting and controlled shutdown.',measure:['Correctness and uncorrected-error log','Sustained useful throughput','Input power and junction / cold-plate temperature','Thermal throttling and shutdown response'],criteria:'Reference outputs agree within the workload tolerance; sustained service and power meet the approved allocation. Junction temperatures remain inside the allocated operating envelope. Radiation tolerance requires separate parts assessment and evidence.',sources:['flight-a100','flight-avionics','flight-rha'],emc:true},
 '01.02':{purpose:'Host software, memory and the tray carrier connect accelerator boards to a serviceable payload assembly.',setting:'electrical-bench',title:'Host, memory and tray interface checkout',requirement:'The host and tray assembly shall boot, address its installed memory and exchange data with each populated payload interface.',approach:'Use a representative populated tray, production firmware, memory diagnostics and interface traffic. Verify boot paths, reset, telemetry and controlled fault recovery at approved voltage and thermal corners.',measure:['Memory errors and address coverage','Boot / watchdog recovery','Host-to-accelerator traffic','Carrier contact and thermal-interface condition'],criteria:'Installed interfaces are enumerated, memory coverage and data integrity satisfy the approved test specification, and faults produce the defined recoveries without an uncontrolled power state.',sources:['flight-dgx','flight-avionics'],emc:true},
 '01.03':{purpose:'Store inputs, model weights and returned products, while preserving integrity over the write-life allocation.',setting:'electrical-bench',title:'Storage integrity, endurance allocation and recovery',requirement:'The storage assembly shall provide the allocated usable capacity, throughput and data integrity through the mission workload.',approach:'Write and read controlled datasets, verify checksums, exercise recovery after approved power interruptions and review supplier endurance against the modeled write workload. Destructive endurance work belongs on representative qualification articles.',measure:['Addressable and usable capacity','Read / write throughput and latency','Checksum and error-correction reports','Power-loss recovery and recorded write volume'],criteria:'Capacity and service performance meet the approved workload requirement; recorded data survive specified interruptions. Endurance and radiation evidence cover the selected device, firmware and mission, with reserve explicitly allocated.',sources:['flight-micron','flight-fsm','flight-rha'],emc:true},
 '01.04':{purpose:'Move payload traffic between trays, storage and the spacecraft data-handling boundary.',setting:'electrical-bench',title:'Network load and fault containment',requirement:'The network fabric shall carry allocated traffic without violating error, latency or isolation requirements.',approach:'Connect representative endpoints and flight-like links. Sweep defined traffic patterns, congestion and link faults, then check routing recovery, telemetry and separation of command traffic from bulk payload traffic.',measure:['Useful throughput and packet / frame errors','Latency under competing traffic','Link recovery and congestion behavior','Switch power'],criteria:'The approved traffic matrix, latency and error limits are met, and faults remain within the defined containment boundary. A nominal line rate alone is not end-to-end verification.',sources:['flight-quantum','flight-spacewire','flight-avionics'],emc:true},
 '02.01':{purpose:'Convert sunlight to protected electrical power and deploy a stable array geometry.',setting:'electrical-bench',title:'Solar-array electrical and deployment performance',requirement:'The deployed array shall deliver its allocated power and preserve electrical continuity across the deployment and tracking range.',approach:'Measure calibrated illuminated or simulated I–V characteristics by string and protected channel. Demonstrate deployment with representative restraints and gravity offload; inspect cell and interconnect damage before and after the applicable environmental sequence.',measure:['String I–V curve and isolation','Protected-channel continuity','Deployed geometry and latch indication','Cell / coverglass / interconnect damage'],criteria:'Measured string output supports the approved beginning/end-of-life power allocation after documented irradiance and temperature corrections; deployment completes without interference and all required latch indications agree.',sources:['flight-spectrolab','flight-rosa','flight-rosa-nasa'],emc:true,animation:'deployment'},
 '02.02':{purpose:'Store electrical energy for eclipse and transient loads, with pack-level sensing and protection.',setting:'electrical-bench',title:'Battery capacity, balance and protective functions',requirement:'The battery assembly shall deliver the allocated usable energy and power while maintaining cell and pack limits.',approach:'Use a bidirectional battery cycler and instrument individual cells and pack boundaries. Measure capacity at specified rates and temperatures; verify balancing, telemetry and protective thresholds using approved stimuli. Cell-abuse and life investigations use separate representative articles.',measure:['Delivered Ah / Wh and efficiency','Cell-voltage spread and temperatures','Charge / discharge current','Protection, isolation and telemetry behavior'],criteria:'Delivered energy and power meet approved state-of-charge, rate and temperature limits; no cell violates its allocated limits and protection transitions match the controlled battery specification. The existing battery size is a sizing input, not an accepted test capacity.',sources:['flight-ves16','flight-battery-workshop','mat-orion-battery'],emc:true},
 '02.03':{purpose:'Condition solar and battery power, regulate buses and contain electrical faults.',setting:'electrical-bench',title:'PCDU regulation and protection coordination',requirement:'Power conditioning and distribution shall maintain allocated bus quality and isolate faults without losing protected essential loads.',approach:'Use source/battery simulators and programmable loads. Exercise MPPT, charge/discharge transitions, load steps, minimum/maximum sources, start-up and controlled branch faults using flight-representative harness impedance.',measure:['Rail regulation and ripple','Conversion efficiency and temperature','Inrush and transient recovery','Branch trip thresholds and essential-load continuity'],criteria:'Bus voltage, ripple, transient and protection behavior meet the approved electrical interface control document; branch limits and selective fault isolation are demonstrated with representative loads.',sources:['flight-crisa','flight-power','v-gevs-emc'],emc:true},
 '03.01':{purpose:'Reject payload and service heat to the modeled environment through a controlled emitting surface.',setting:'thermal-vacuum',title:'Radiator heat-path and thermal-balance correlation',requirement:'The radiator assembly shall reject its allocated heat while maintaining permissible gradients and interface temperatures.',approach:'Inspect surface optical properties and bonds, apply measured heat at representative interfaces and simulate the relevant radiative boundaries in vacuum. Compare pre/post mechanical-exposure heat maps; correlate a model that includes chamber fixtures and targets.',measure:['Applied heat and boundary temperatures','Radiator temperature field / gradients','Surface absorptance and emittance evidence','Heat-path resistance and model residuals'],criteria:'The approved thermal cases meet temperature and gradient allocations and the correlation criteria; optical properties are supported by measurements or controlled lot evidence. Radiator area alone does not demonstrate on-orbit capacity.',sources:['v-gevs-balance','flight-thermal','mat-act-radiator'],mechanical:true,thermal:false,animation:'deployment'},
 '03.02':{purpose:'Move heat from the compute interface to the radiator using the selected thermal architecture.',setting:'pressure-bench',title:'Heat-transport performance and integrity',requirement:'The selected transport assembly shall carry allocated heat while preserving its pressure, temperature and containment boundaries.',approach:'Measure thermal transport and, for pumped circuits, pressure drop, flow, leak integrity and start/restart behavior. Reproduce representative bends, fittings, bypass states and control logic before correlating the thermal/hydraulic model.',measure:['Heat transported and temperature rise','Flow and pressure drop where applicable','Leak integrity and control response','Duty / standby transfer for installed pumps'],criteria:'Heat transport meets the approved allocation within component limits. Fluid, seals, materials and cleanliness must be selected and compatible; proof, leak and allowable pressure values come from the approved pressure-system design.',sources:['flight-iss-thermal','flight-act','v-gevs-clean'],thermal:true},
 '03.03':{purpose:'Limit parasitic heat exchange while preserving vents, electrical bonds, access and sensitive-surface clearance.',setting:'clean-inspection',title:'MLI fit, workmanship and thermal boundary',requirement:'Each blanket shall match its installation definition and achieve its allocated thermal function without obstructing another interface.',approach:'Inspect blanket layup and identification, seams, penetrations, grounding tabs, vent paths and attachment spacing. Fit the blanket to the actual assembly, then use assembly thermal-balance evidence to correlate its installed behavior.',measure:['Blanket coverage and vent / interface clearance','Layup and process traceability','Bond continuity where specified','Installed temperature and heat-leak evidence'],criteria:'The approved pattern, materials, coverage, attachments and bond requirements are satisfied. Effective emissivity and seam heat leak are established for the installed blanket; a layer count or gold appearance is insufficient.',sources:['flight-mli','mat-sheldahl','v-gevs-balance'],mechanical:false,thermal:false},
 '04.01':{purpose:'Exchange angular momentum to control spacecraft attitude; mounting and disturbances matter as much as catalog torque.',setting:'electrical-bench',title:'CMG torque, momentum and disturbance characterization',requirement:'The CMG assembly shall meet its allocated momentum and torque envelope and report controlled state throughout commanded operation.',approach:'Use a characterized dynamometer or torque fixture and representative drive electronics. Exercise rotor/gimbal commands, limits and telemetry; measure disturbances and power. Correlate steering and singularity handling in a hardware-in-the-loop simulation.',measure:['Rotor momentum and torque response','Gimbal rate / position and limit behavior','Disturbance force / torque spectrum','Power, temperature and fault telemetry'],criteria:'Approved actuator envelope, control response and disturbance allocations are met over operating corners; steering analysis covers the installed pyramid and mission demand. Catalog single-unit values are not guaranteed cluster authority.',sources:['flight-cmg','flight-cmg-design','flight-gnc'],emc:true,animation:'cmg'},
 '04.02':{purpose:'Create a magnetic dipole to unload momentum where the orbit and field geometry permit.',setting:'electrical-bench',title:'Magnetorquer dipole and magnetic cleanliness',requirement:'The magnetic actuator shall provide its allocated dipole and controllability without violating magnetic-interference limits.',approach:'Drive the rod in a calibrated magnetic-field measurement fixture, measure dipole versus current and temperature, then verify polarity and command response in the flight coordinate convention. Analyze unloading with the actual orbit and control law.',measure:['Dipole vector versus current','Winding resistance and temperature','Residual magnetism and polarity','Command / current telemetry'],criteria:'Allocated dipole, resistance, thermal and residual-field limits are met. Unloading capability must be demonstrated by mission-specific control analysis; a dipole rating is not a constant torque rating.',sources:['flight-rod','mat-magnetorquer','flight-gnc'],emc:true},
 '04.03':{purpose:'Provide calibrated attitude observations and time-tagged data to the attitude-control system.',setting:'optical-bench',title:'Sensor calibration, alignment and validity flags',requirement:'Attitude sensors shall meet allocated accuracy, availability and timing requirements in the installed coordinate frame.',approach:'Use calibrated optical/electrical stimuli and reference attitudes, including acquisition, blinded or invalid conditions and recovery. Measure alignment to mechanical datums and propagate the uncertainty into the installed pointing budget.',measure:['Bias, noise and alignment error','Acquisition / recovery time','Timestamp and data validity','Stray-light and exclusion behavior'],criteria:'Accuracy and timing meet the approved sensor and system budgets; invalid observations are correctly identified. Supplier reference hardware and a rendered baffle do not establish flight sensor selection.',sources:['flight-hydra','flight-gnc','mat-hydra'],emc:true},
 '05.01':{purpose:'Maintain the independent command, telemetry and tracking connection.',setting:'rf-chamber',title:'TT&C command loop and antenna pattern',requirement:'The S-band chain shall command and report spacecraft state at the allocated link and interface conditions.',approach:'First close a conducted or shielded command loop with calibrated attenuation and known data. Separately measure antenna match and radiation performance in a qualified range/chamber; verify compatibility and flight-harness electromagnetic behavior.',measure:['RF output / receiver sensitivity','Bit or frame error rate and command acknowledgement','Antenna match and pattern','Timing, polarization and isolation'],criteria:'The approved TT&C link, antenna and command-response requirements are met. A test hat verifies a coupled functional path; it does not establish a far-field antenna pattern or an operational ground-station link.',sources:['flight-anywaves','flight-comms','ground-eo1'],emc:true},
 '05.02':{purpose:'Transfer high-rate data through the reflector, RF electronics and pointing mechanism.',setting:'rf-chamber',title:'Ka-band RF chain and pointed antenna verification',requirement:'The Ka-band assembly shall meet its allocated gain, pointing, data-rate and spectral requirements throughout its usable pointing range.',approach:'Calibrate the conducted chain and bit comparator, survey the reflector/feed alignment and characterize the radiated antenna in an appropriate range. Exercise the positioner and verify boresight, keep-out zones and return-to-reference behavior.',measure:['Gain / pattern / polarization','RF power and receive performance','Error rate under calibrated attenuation','Boresight and positioner repeatability'],criteria:'Approved link-budget terms and pointing allocations are supported by measurements and analysis; conducted power and error-rate tests cannot substitute for antenna-pattern evidence.',sources:['flight-comms','flight-nisar','ground-rf-scoe'],emc:true,animation:'terminals'},
 '05.03':{purpose:'Exchange optical data while maintaining precise pointing, acquisition and tracking.',setting:'optical-bench',title:'Optical boresight, acquisition and data integrity',requirement:'The optical terminal shall acquire the representative link and meet allocated pointing and data-integrity limits.',approach:'Use calibrated targets, attenuation and motion stimuli in an enclosed optical setup. Measure boresight and jitter, run acquisition/tracking and known-data transfers, then compare alignment before/after environmental exposure.',measure:['Boresight and jitter','Acquisition / reacquisition time','Optical power and wavefront where allocated','Data errors versus calibrated receive conditions'],criteria:'The approved pointing, optical and data-link allocations are met with documented measurement uncertainty. Atmospheric availability and ground-station performance remain separate link-system obligations.',sources:['flight-tbird','flight-tesat','flight-click'],emc:true,animation:'terminals'},
 '06.01':{purpose:'Convert controlled propellant flow into commanded impulse for maneuvers and disposal.',setting:'propulsion-stand',title:'Thruster performance and valve integrity',requirement:'The thruster/valve assembly shall produce the allocated impulse while containing propellant and respecting duty and thermal limits.',approach:'Review supplier qualification and lot evidence; plan representative hot-fire performance and life work in a controlled facility, plus article-specific valve, leak and electrical acceptance checks. Correlate thrust and impulse models using the applicable pressure and thermal boundaries.',measure:['Thrust / impulse and mixture response','Valve leakage and actuation','Inlet conditions and temperatures','Ignition, shutdown and accumulated duty'],criteria:'The approved thrust, specific impulse, impulse-bit, leakage and life requirements are covered by applicable evidence. Rendered plumes and simulation motion are not firing data.',sources:['flight-engine','flight-propulsion','mat-s400'],thermal:false},
 '06.02':{purpose:'Regulate and distribute propellant and pressurant through separated, compatible paths.',setting:'pressure-bench',title:'Feed-system integrity and regulator performance',requirement:'The feed assembly shall deliver the allocated pressure and flow while maintaining fuel, oxidizer and pressurant isolation.',approach:'Verify line identity and cleanliness; characterize regulators, valve states and flow losses with approved test media and representative plumbing. Plan pressure-integrity evidence and pre/post leak checks under the approved pressure-system specification.',measure:['Regulated pressure and transient response','Flow / pressure loss','Internal and external leakage','Valve state and cross-path isolation'],criteria:'Allocated delivery pressure and stability are achieved without incompatible cross-connection or unresolved leakage. Proof and leak limits, media compatibility and cleanliness are specific to the controlled pressure-system design.',sources:['flight-feed','flight-fluid-compatibility','v-gevs-clean']},
 '06.03':{purpose:'Contain the fuel inventory and provide the required propellant acquisition behavior.',setting:'pressure-bench',title:'Fuel vessel integrity and acquisition evidence',requirement:'The fuel vessel, mounts and propellant management device shall contain the allocated fuel and deliver it within the defined mission conditions.',approach:'Review material, weld and nondestructive-inspection records; plan controlled proof/leak verification and mount load assessment. Correlate fill/expulsion and propellant-management behavior using applicable supplier tests and mission analysis.',measure:['Volume and dry mass','Pressure / leak response','NDE and joint / mount condition','Usable and residual propellant evidence'],criteria:'The approved pressure, fracture-control, cleanliness and mount requirements are closed; usable fuel and residual allocation agree with applicable acquisition evidence. The geometric sphere is a sizing representation.',sources:['flight-pmd','flight-sp8112','flight-fluid-compatibility'],thermal:false},
 '06.04':{purpose:'Contain oxidizer separately from fuel while preserving cleanliness and usable inventory.',setting:'pressure-bench',title:'Oxidizer vessel compatibility and integrity',requirement:'The oxidizer vessel and acquisition hardware shall contain the allocated oxidizer without unacceptable contamination, leakage or structural degradation.',approach:'Trace wetted materials, weld/NDE and cleanliness records to the oxidizer service. Plan vessel and mount verification, approved pressure/leak checks and acquisition/residual evidence; keep all compatibility assumptions explicit.',measure:['Volume and dry mass','Material / process compatibility records','Leak and pressure data','Acquisition and residual inventory evidence'],criteria:'The controlled pressure-system, fracture, cleanliness and oxidizer-compatibility requirements are satisfied. Similar fuel-tank geometry is not evidence of oxidizer compatibility.',sources:['flight-pmd','flight-sp8112','flight-fluid-compatibility'],thermal:false},
 '06.05':{purpose:'Store pressurant and supply the allocated pressure history while managing vessel life.',setting:'pressure-bench',title:'Pressurant bottle integrity and life evidence',requirement:'The pressurant vessel shall retain the allocated charge throughout its approved pressure, thermal and life envelope.',approach:'Review liner/overwrap material and manufacturing records, NDE, pressure-cycle history and supplier qualification. Plan article proof/leak acceptance and verify mounts; assess composite stress-rupture or fatigue life using the actual vessel design.',measure:['Pressure / temperature / charge','Leakage','NDE and material traceability','Pressure-cycle and service-life record'],criteria:'The selected vessel’s approved pressure, life and inspection criteria are met with an article-specific record. Neither a modeled shell mass nor an assumed burst factor establishes a certified vessel.',sources:['flight-pressurant-tank','flight-copv-life','mat-copv'],thermal:false},
 '07.01':{purpose:'Carry payload, launch and mechanism loads through a known stiffness and load path.',setting:'load-frame',title:'Primary structure strength and model correlation',requirement:'The primary structure shall carry approved load combinations without unacceptable yielding, instability or interface distortion.',approach:'Create a controlled structural model including joints and mounted equipment, correlate its dynamic behavior, and apply the selected strength-verification approach. Measure strain, displacement and interface reactions during an approved test.',measure:['Strain / displacement / reaction loads','Mode shapes and frequencies','Joint preload and slip','Residual deformation and NDE'],criteria:'Approved stress, buckling, stiffness and interface criteria are met with the adopted factors and correlated model. Load cases, allowables and factors are project requirements; no numerical strength margin is inferred from the mesh.',sources:['v-gevs-mechanical','flight-structure'],thermal:false},
 '07.02':{purpose:'Enclose the spacecraft and transfer panel loads while preserving penetrations and thermal boundaries.',setting:'load-frame',title:'Sandwich-panel bond, insert and load verification',requirement:'The enclosure panels and inserts shall carry their allocated loads and preserve the required enclosure and interface geometry.',approach:'Trace skin/core/adhesive processes, inspect bond quality and inserts, and correlate representative panel/load-path tests with analysis. Include pressure equalization and thermal-distortion effects at penetrations.',measure:['Bond and core integrity','Insert pull-out / shear evidence','Panel stiffness and deflection','Vent / feedthrough and seal condition'],criteria:'Material/process evidence and approved panel, insert and deformation limits are satisfied; acceptance NDE covers the manufactured panels and any repaired areas.',sources:['flight-hexweb','flight-structure','mat-act-radiator'],thermal:false},
 '07.03':{purpose:'Reduce the radiation environment at selected electronics using a controlled shielding geometry.',setting:'review',title:'Radiation transport and installed shielding inspection',requirement:'The shielding design shall support the allocated electronics radiation tolerance without violating mass, thermal or structural interfaces.',approach:'Build a mission radiation environment and as-built shielding model; evaluate dose and particle effects at sensitive devices. Review selected part evidence, inspect installed coverage and penetrations, and use component irradiation evidence where required.',measure:['Material and areal-density traceability','Shield coverage and penetrations','Predicted dose / particle environment','Device tolerance and mitigation evidence'],criteria:'The approved radiation hardness assurance assessment closes dose and relevant single-event risks with documented margins. Material color, bulk shield mass or a nominal wall thickness alone does not demonstrate protection.',sources:['flight-rha','flight-juno','mat-radiation'],mechanical:false,thermal:false,methods:['analysis','inspection']},
 '07.04':{purpose:'Restrain appendages for launch and deploy or track them reliably in the mission environment.',setting:'deployment',title:'Deployment, force margin and mechanism life',requirement:'Each deployment and tracking mechanism shall release, move and latch through its commanded range with approved force and life margins.',approach:'Use representative appendages, gravity offload and worst-case interfaces. Measure available/resisting torque across temperature and life; demonstrate release/latch logic, repeatability, clearance and recovery from defined off-nominal states.',measure:['Torque / force versus travel','Latch / release state and timing','Clearance and final alignment','Life-cycle count, wear and power'],criteria:'Approved end-of-life force/torque margin and functional criteria are met across the allocated operating range. Animation demonstrates the intended sequence only; it does not measure friction or qualify a latch.',sources:['v-gevs-mechanism','flight-sada'],animation:'deployment',emc:true},
 '07.05':{purpose:'Route protected power and data while preserving isolation, grounding, strain relief and motion clearance.',setting:'electrical-bench',title:'Harness continuity, isolation and installed routing',requirement:'The harness shall connect the correct interfaces with allocated electrical characteristics and protected routing.',approach:'Inspect workmanship and connector keying, verify point-to-point continuity and isolation using equipment compatible with attached electronics, and measure loaded voltage drop. Check bend/strain relief, shield terminations and moving-interface clearance before mating.',measure:['Pin-to-pin continuity and isolation','Loaded voltage drop / contact resistance','Shield and bond continuity','Bend radius, strain relief and chafe clearance'],criteria:'The approved pin list, wire/current ratings, isolation and workmanship limits are met; no ambiguous connector mate or motion interference remains. Test voltage and connection state require procedure approval.',sources:['flight-harness','flight-workmanship','v-gevs-function'],mechanical:false,thermal:false,emc:true},
 '08.01':{purpose:'Execute flight control, timekeeping, command handling and navigation with controlled fault recovery.',setting:'electrical-bench',title:'Avionics hardware-in-the-loop mission checkout',requirement:'Flight avionics shall execute the defined command, navigation and fault-management functions with allocated timing and integrity.',approach:'Connect flight software to controlled sensor, navigation and bus simulators. Exercise command validity, telemetry, watchdog/redundancy, safe mode and clock/time-tag behavior; repeat key functions at voltage and thermal corners.',measure:['Command / telemetry correctness','Timing and navigation errors','Fault detection and recovery','Bus and power behavior'],criteria:'Approved functional, timing and fault-response requirements are met for the controlled hardware/software build. Simulator truth, stimulus versions and interface models remain traceable.',sources:['flight-iau','flight-gnss','flight-avionics','ground-simulation'],emc:true},
 '09.01':{purpose:'Transfer spacecraft loads into the launcher and release a compatible, clean flight interface.',setting:'fit-check',title:'Adapter fit and separation-interface verification',requirement:'The adapter and separation interface shall satisfy the approved launcher ICD and release the spacecraft within its separation requirements.',approach:'Inspect bolt-circle and datum geometry, mating surfaces and connector routing. Correlate load and separation analyses with approved provider/interface tests, including release function, tip-off, clearance and shock evidence at the appropriate article level.',measure:['Mating geometry and preload records','Load-path / stiffness evidence','Release state, clearance and separation dynamics','Connector release and shock environment'],criteria:'The agreed payload/launcher interface and separation requirements are closed by applicable analysis, fit inspection and provider evidence. A fairing-fit animation does not establish bolt pattern, separation speed or shock qualification.',sources:['flight-separation','flight-lightband','flight-falcon-guide'],thermal:false},
};

function fieldAnalysis(id,title,kind,description,inputs,outputs,limits,sources=[],equation){return {id,title,kind,description,inputs,outputs,equation,limits,sources,status:'study'};}
function flightAnalyses(r,h){
 const w=r.wbs||r.id.slice(7),i=h.input||{},e=h.energySystem?.electrical||{},t=h.energySystem?.thermal||{},a=[];
 const sourceBasis='Existing workbench sizing model for the current design; not hardware measurement or a compliance result.';
 const live=(label,value,unit)=>datum(label,value??'Unallocated',unit,sourceBasis);
 if(['01.01','01.02'].includes(w))a.push(fieldAnalysis('compute-load','Payload load and thermal boundary','power','These allocations define a useful loaded-test configuration. The representative workload and allowable errors still need a controlled test specification.',[live('Installed trays',h.trays,''),live('Installed electronics',h.installedElectronicsKw,'kW'),live('Active payload power',h.itKw,'kW')],[live('Payload junction limit',i.junctionLimitK,'K'),live('Cold-plate operating minimum',i.coldPlateOpMinK,'K'),live('Cold-plate operating maximum',i.coldPlateOpMaxK,'K')],['Temperature inputs are operating allocations, not chamber qualification set points.','Throughput predictions require calibrated flight-hardware benchmarks.'],['flight-dgx','v-gevs-function']));
 if(w==='01.03')a.push(fieldAnalysis('storage-allocation','Usable storage and workload boundary','interfaces','Compare delivered capacity and sustained I/O evidence to the active design, including its reserve and model-weight allocation.',[live('Installed capacity',h.storageTB,'TB'),live('Model weights',h.weightsTB,'TB'),live('Initial queue',h.initialQueueGB,'GB')],[live('Usable capacity',h.usableTB,'TB'),live('Modeled read service',h.diskReadGBs,'GB/s'),live('Modeled write service',h.diskWriteGBs,'GB/s')],['Predicted I/O is not measured endurance or radiation evidence.','Retention, write amplification, wear reserve and power-loss behavior require device/firmware-specific review.'],['flight-micron']));
 if(w==='01.04')a.push(fieldAnalysis('fabric-allocation','Fabric and end-to-end traffic','interfaces','A port-rate allocation is one boundary in the data path. Test competing workloads and software processing across all endpoints.',[live('Allocated fabric line rate',i.fabricGbps,'Gbit/s'),live('Payload trays',h.trays,'')],[live('Fabric power allocation',h.switchKw,'kW'),live('Allocated bulk downlink rate',i.bulkMbps,'Mbit/s')],['No latency, congestion or packet-loss solver is run by this panel.','Protocol overhead and end-to-end goodput require representative traffic measurements.'],['flight-quantum','flight-spacewire']));
 if(w==='02.01')a.push(fieldAnalysis('solar-allocation','Array sizing and source-voltage screen','power','The current area and conversion architecture define the electrical screen to be correlated with selected-cell and string test data.',[live('Solar area',h.solarM2,'m²'),live('Wing count',h.solarWingCount,''),live('Area efficiency input',i.pvEfficiency,'fraction')],[live('Beginning-of-life array model',e.bolArrayKW,'kW'),live('Cold open-circuit estimate',e.source?.estimatedColdVocV,'V'),live('Hot MPP estimate',e.source?.estimatedHotMppV,'V')],['Electrical estimates use project cell/temperature assumptions, not a selected flight-cell IV qualification.','Illumination, degradation, pointing, harness and conversion losses remain distinct.'],['flight-spectrolab','flight-crisa']));
 if(w==='02.02'){
  const usable=finite(h.batteryKWh)&&finite(i.socMax)&&finite(i.socMin)?h.batteryKWh*(i.socMax-i.socMin):undefined;
  a.push(fieldAnalysis('battery-energy','Battery energy window','power','This arithmetic identifies the nominal energy between the selected state-of-charge limits. It is a planning bound for capacity testing.',[live('Nominal pack energy',h.batteryKWh,'kWh'),live('Minimum state of charge',i.socMin,'fraction'),live('Maximum state of charge',i.socMax,'fraction')],[live('Nominal energy in SOC window',usable,'kWh'),live('Bus discharge converter limit',e.battery?.dischargeBusLimitKW,'kW'),live('Bus charge converter limit',e.battery?.chargeBusLimitKW,'kW')],['This window excludes aging, temperature, rate-dependent capacity, conversion loss and reserve.','Operational/survival temperatures and cell protective thresholds must be verified separately.'],['flight-battery-workshop'],'Ewindow = Enominal × (SOCmax − SOCmin)'));
 }
 if(w==='02.03')a.push(fieldAnalysis('eps-balance','Electrical allocation and capacity screen','power','Read the existing EPS model at its peak design load. Capacity differences are study headroom, not verified hardware margin.',[live('Primary bus',e.distribution?.nominalBusV,'V'),live('Peak modeled demand',e.peakBusDemandKW,'kW'),live('Distribution capacity',e.distribution?.capacityKW,'kW')],[live('Distribution study headroom',finite(e.distribution?.capacityKW)&&finite(e.peakBusDemandKW)?e.distribution.capacityKW-e.peakBusDemandKW:undefined,'kW'),live('Conversion loss',e.peakConversionLossKW,'kW'),live('Harness loss',e.peakHarnessLossKW,'kW')],['Rated modules and protection thresholds are project allocations pending selected hardware evidence.','Transient, stability, fault isolation and electromagnetic performance need test/model correlation.'],['flight-crisa'],'Headroom = allocated distribution capacity − modeled peak bus demand'));
 if(['03.01','03.02','03.03'].includes(w)){
  const passive=t.kind==='passive-local',lift=t.kind==='heat-lift';
  a.push(fieldAnalysis('thermal-path',passive?'Passive heat-path allocation':lift?'Heat-lift energy balance':'Heat and flow allocation','thermal','Use the selected architecture rather than assuming every design has an ammonia pump. The data below come from the current thermal sizing model.',[live('Thermal architecture',t.kind,''),live('Design heat',t.designHeatKW,'kW'),live('Radiator area',h.radiatorM2,'m²')],passive?[live('Transport capacity',t.transportCapacityKW,'kW'),live('Nominal conductance',t.nominalConductanceKWK,'kW/K')]:lift?[live('Heat-lift electrical allocation',t.heatPumpDesignKW,'kW'),live('Transport capacity',t.transportCapacityKW,'kW')]:[live('Required flow',t.requiredFlowKgS,'kg/s'),live('Design fluid rise',t.designDeltaK,'K'),live('Calculated loop loss',t.atRequired?.totalPa,'Pa')],['These are preliminary model values; material properties, interfaces and selected equipment need correlation.','Thermal balance must model chamber targets, fixtures and hot/cold/survival flight boundaries.'],['v-gevs-balance','flight-thermal'],passive?'Q = G × ΔT (within transport limits)':lift?'Qhot = Qcold + Welectrical':'Q = mass flow × heat capacity × temperature rise'));
 }
 if(w==='04.01')a.push(fieldAnalysis('cmg-allocation','Cluster authority allocation','interfaces','The workbench reduces the sum of single-unit values using its directional factor. It does not solve the steering singularity envelope here.',[live('CMGs',h.cmg?.count,''),live('Unit momentum',h.cmg?.rawUnitMomentumNms,'N·m·s'),live('Directional factor',h.cmg?.directionalFactor,'')],[live('Planned momentum',h.cmg?.plannedMomentumNms,'N·m·s'),live('Planned torque',h.cmg?.plannedTorqueNm,'N·m'),live('Maneuver power',h.cmg?.maneuverW,'W')],['Catalog values do not establish complete cluster authority in every direction.','Installed geometry, steering law, disturbance budget, life and thermal conditions require verification.'],['flight-cmg','flight-cmg-design'],'Planned momentum = count × unit momentum × directional factor'));
 if(w==='04.02')a.push(fieldAnalysis('magnetic-allocation','Magnetic unloading boundary','interfaces','The selected dipole is an actuator allocation. Torque also depends on the local field and angle, so unloading requires orbital control analysis.',[live('Allocated dipole',i.dipoleAm2,'A·m²'),live('Orbit altitude',i.altitudeKm,'km'),live('Inclination',i.inclinationDeg,'deg')],[datum('Torque authority','Requires field-vector history and control simulation')],['No constant torque or guaranteed momentum dump time is inferred.'],['flight-rod','flight-gnc'],'Torque vector = magnetic dipole vector × magnetic field vector'));
 if(['04.03','05.03'].includes(w))a.push(fieldAnalysis('pointing-allocation','Optical pointing allocation','interfaces','A small rendered aperture still depends on alignment, jitter, attitude knowledge and thermal stability.',[live('Optical aperture',i.opticalApertureM,'m'),live('Optical jitter allocation',i.opticalJitterUrad,'µrad')],[datum('Installed boresight uncertainty','Unallocated'),datum('Thermoelastic alignment evidence','Not yet measured')],['Optical terminal allocations do not substitute for an attitude-sensor accuracy requirement.','No alignment or line-of-sight solution is generated here.'],['flight-tbird','flight-gnc']));
 if(['05.01','05.02'].includes(w))a.push(fieldAnalysis('rf-allocation','Communications test boundary','interfaces','The interface allocation identifies the traffic or aperture to verify; test calibration and the mission link budget remain necessary.',[live('Command rate',i.commandKbps,'kbit/s'),live('Ka aperture',i.kaDishM,'m'),live('Link-capacity input',i.linkCapMbps,'Mbit/s')],[datum('Measured gain / receiver sensitivity','Pending'),datum('Operational station compatibility','Separate end-to-end verification')],['These values do not establish an RF link margin, frequency authorization or antenna pattern.'],['flight-comms','ground-rf-scoe']));
 if(/^06\./.test(w)){
  const tankKey={'06.03':'fuel','06.04':'oxidizer','06.05':'helium'}[w],tank=h.propulsion?.tanks?.find(t=>t.id===tankKey);
  if(tank)a.push(fieldAnalysis('vessel-allocation','Vessel sizing boundary','geometry','The tank model defines a preliminary envelope and volume. Pressure-system verification belongs to the selected vessel design and its life record.',[live('Modeled volume',tank.volumeL,'L'),live('Modeled radius',tank.radiusM,'m'),live('Shell mass estimate',tank.shellKg,'kg')],[live('Bottle pressure input',h.propulsion?.bottlePa,'Pa'),live('Feed pressure input',h.propulsion?.feedPa,'Pa')],['Bottle and feed pressure are different system boundaries; they are not universal vessel proof pressures.','Sphere radius and shell mass do not provide wall allowables, weld quality or certified pressure capacity.'],['flight-sp8112','flight-pmd']));
  else a.push(fieldAnalysis('propulsion-allocation','Propulsion sizing and performance boundary','interfaces','These mission inputs define the preliminary propulsion allocation and test questions.',[live('Modeled fuel',h.fuelKg,'kg'),live('Modeled oxidizer',h.oxidizerKg,'kg'),live('Modeled pressurant',h.pressurantKg,'kg')],[live('Specific impulse input',i.isp,'s'),live('Thrust input',i.thrustN,'N')],['The sizing model has no supplier hot-fire or pressure-qualification result.','Consumption, residuals, delivery pressure and life require article- and mission-specific evidence.'],['flight-propulsion','flight-engine']));
 }
 if(['07.01','07.02','07.04','09.01'].includes(w))a.push(fieldAnalysis('integration-envelope','Current integration envelope','geometry','Use the current geometric fit screen to identify interfaces requiring tolerance analysis and physical verification.',[live('Stowed diameter',h.stowedDiameterM,'m'),live('Stowed length',h.stowedLengthM,'m'),live('Launch mass allocation',h.launchKg,'kg')],[live('Modeled radial clearance',h.radialClearanceM,'m'),live('Modeled axial clearance',h.axialClearanceM,'m')],['Clearance is a study geometry result; manufacturing tolerance, deflection, dynamics and assembly access are not verified by this screen.','Structural modes, stresses and separation motion require their own controlled models/tests.'],['v-gevs-mechanical','flight-falcon-guide']));
 if(w==='07.03')a.push(fieldAnalysis('shielding-allocation','Radiation shielding allocation','interfaces','Use the actual shield allocation as a model input. Radiation transport and selected-device evidence are still open.',[live('Payload shield allocation',h.payloadShieldKg,'kg'),live('Wall shielding areal allocation',i.shieldKgM2,'kg/m²'),live('Mission duration',i.missionYears,'years')],[datum('Dose / SEE closure','Requires environment, transport and device evidence')],['No dose reduction or radiation qualification is calculated from this mass.'],['flight-rha','flight-juno']));
 if(w==='07.05'){
  const x=e.harness?.primary;
  a.push(fieldAnalysis('harness-allocation','Primary power harness screen','power','The current routing and conductor allocation inform loaded-drop and thermal verification.',[live('Primary circuits',x?.count,''),live('One-way route',x?.lengthM,'m'),live('Conductor section',x?.areaMM2,'mm²')],[live('Modeled resistance',x?.resistanceOhm,'Ω'),live('Rated drop fraction',x?.ratedDropFraction,'fraction'),live('Current rating allocation',x?.currentRatingA,'A')],['Hot-wire resistivity and routing assumptions require selected-wire, connector and thermal evidence.','This screen does not establish insulation, workmanship or electromagnetic compliance.'],['flight-harness','flight-workmanship'],'Voltage drop = current × loop resistance'));
 }
 return a;
}

// Expose current design allocations as planning targets without presenting them
// as approved qualification levels or measured article acceptance results.
function currentFunctionalTargets(r,h){
 const w=r.wbs||r.id.slice(7),i=h.input||{},e=h.energySystem?.electrical||{},t=h.energySystem?.thermal||{},out=[];
 const add=(label,value,unit)=>{if(finite(value))out.push(label+' '+pretty(value,4)+' '+unit);};
 if(w==='01.01'){add('payload power',h.itKw,'kW');add('junction upper operating limit',i.junctionLimitK,'K');}
 if(w==='01.03'){add('usable storage allocation',h.usableTB,'TB');add('modeled read service',h.diskReadGBs,'GB/s');}
 if(w==='02.01'){add('beginning-of-life modeled array power',e.bolArrayKW,'kW');add('source open-circuit limit',e.source?.maxOpenCircuitV,'V');}
 if(w==='02.02'){
  if(finite(h.batteryKWh)&&finite(i.socMin)&&finite(i.socMax))add('nominal SOC-window energy before aging/rate/loss corrections',h.batteryKWh*(i.socMax-i.socMin),'kWh');
  add('converter discharge allocation',e.battery?.dischargeBusLimitKW,'kW');add('battery operating minimum',i.batteryOpMinK,'K');add('battery operating maximum',i.batteryOpMaxK,'K');
 }
 if(w==='02.03'){add('primary bus',e.distribution?.nominalBusV,'V');add('peak modeled bus demand',e.peakBusDemandKW,'kW');}
 if(w==='03.01'){add('thermal design heat',t.designHeatKW,'kW');add('radiator area',h.radiatorM2,'m²');}
 if(w==='03.02'){add('thermal design heat',t.designHeatKW,'kW');if(!['passive-local','heat-lift'].includes(t.kind))add('required flow',t.requiredFlowKgS,'kg/s');}
 if(w==='04.01'){add('planned cluster momentum',h.cmg?.plannedMomentumNms,'N·m·s');add('planned cluster torque',h.cmg?.plannedTorqueNm,'N·m');}
 if(w==='04.02')add('dipole allocation',i.dipoleAm2,'A·m²');
 if(w==='05.03')add('pointing-jitter input',i.opticalJitterUrad,'µrad');
 if(w==='06.01'){add('thrust input',i.thrustN,'N');add('specific-impulse input',i.isp,'s');}
 return out.length?' Current study targets: '+out.join('; ')+'. Confirm these as controlled requirements with uncertainties and operating conditions before test approval; they are not measured results.':'';
}

function inventoryProfile(r,c,h){
 const w=r.wbs||r.id.slice(7),key={'06.06':'fuel','06.07':'oxidizer','06.08':'helium'}[w],parentId={'fuel':'flight:06.03','oxidizer':'flight:06.04','helium':'flight:06.05'}[key],vessel=get(c,parentId);
 const aero=/aerozine/i.test(r.title)||h.input?.engine==='aero';
 const sources=key==='fuel'?(aero?['flight-dla','flight-apollo','flight-fluid-compatibility']:['flight-mmh-spec','flight-mmh-maker']):key==='oxidizer'?['flight-mon-spec','flight-cf-nto']:['flight-helium-supply','flight-fluid-compatibility'];
 const activities=[activity('lot-identity','Commodity lot identity and compatibility',['inspection','analysis'],'clean-inspection',`${r.title} shall conform to the approved commodity specification and be compatible with its wetted containment path.`,
 'Trace supplier certificate, lot, specification revision and sample evidence; review contamination and wetted-material compatibility across storage, servicing lines and flight vessel.',
 ['Certificate and lot identity','Purity / composition / contamination evidence','Wetted-material and seal compatibility'],
 'The approved purchase/commodity specification and contamination requirements are met by traceable lot evidence. Purity and contamination limits are not allocated by the visualization.',{article:'flight',sources,chart:steps('inspection',['Identify lot','Review sample evidence','Check compatibility','Release for loading'])}),
 activity('inventory-loading','Loading quantity and contained-system integrity',['test','inspection'],'pressure-bench',`The approved ${key} inventory shall be transferred into the correct verified containment path with a traceable quantity.`,
 'Plan a controlled, authorized servicing procedure with calibrated quantity and pressure/temperature instrumentation. Reconcile source, transfer and final inventory records; verify vessel and line readiness before connection and retain final leak/integrity evidence.',
 ['Loaded mass or pressure-temperature inventory','Source and destination identity','Transferred / residual quantity reconciliation','Final containment integrity'],
 'The approved loading quantity and uncertainty are satisfied, the correct containment path is documented, and all discrepancies are dispositioned. No stand-alone shaker or thermal-vacuum test is assigned to loose commodity.',{sources:[...sources,'ground-propellants','v-gevs-clean'],chart:steps('sequence',['Verify vessel readiness','Identify lot / path','Controlled load','Reconcile inventory','Release containment'])})];
 const p=profile(`inventory-${key}`,r.title,'Verification follows the procurement lot, measured loading and the vessel that contains the commodity.',activities,{level:'Contained inventory',scope:'The inventory is a mass allocation inside a vessel, not a separately rendered flight component. Commodity receipt and servicing evidence belong to the lot and loading operation; mechanical/thermal verification belongs to the contained system.',defaultSetting:'installed',settings:['studio','installed','clean-inspection','pressure-bench'],sources:['v-plan','v-methods','v-outline','v-integration',...sources],analyses:flightAnalyses(r,h)});
 p.integration={...integrationFor({...r,parentId},c),parentId,title:`Load into ${vessel?.title||parentId}`,steps:['Confirm vessel, feed path, servicing equipment and procedures are released for the specific commodity.','Record lot identity and the calibrated quantity transferred into the correct path.','Close the loading and containment record; include quantity uncertainty and residuals in the flight configuration.']};return p;
}
function flightProfile(r,c,h){
 const w=r.wbs||r.id.slice(7);if(['06.06','06.07','06.08'].includes(w))return inventoryProfile(r,c,h);
 const s=flightSpecs[w];if(!s)return null;
 let spec={...s},extra=[];
 if(w==='03.02'&&h.energySystem?.thermal?.kind==='passive-local')spec={...spec,title:'Passive heat transport and bond characterization',setting:'thermal-vacuum',requirement:'The selected passive transport assembly shall carry the allocated heat while preserving interface temperatures and mechanical/bond integrity; sealed working-fluid integrity applies only where a selected heat-pipe construction has that boundary.',approach:'Characterize the selected spreader, heat pipe or strap path with calibrated heat input, representative interfaces and thermal boundaries. Verify startup, orientation sensitivity during ground testing and transport limit, then correlate the installed thermal model.',measure:['Heat input and temperature difference','Interface conductance','Startup and transport-limit evidence','Bond integrity before / after mechanical exposure'],criteria:'Allocated heat transport and interface temperatures are supported by correlated evidence. No common pumped coolant circuit or separate ammonia service test is imposed on this passive architecture.',sources:['flight-redwire-thermal','mat-heat-pipes','v-gevs-balance']};
 if(w==='03.02'&&h.energySystem?.thermal?.kind==='heat-lift')spec={...spec,title:'Heat-lift capacity, power and startup',approach:'Characterize the selected heat-lift assembly over its cold/hot interface temperatures, including electrical input, startup, controls and representative transport interfaces. Verify any working-fluid pressure system using the selected supplier design.',measure:['Cold-side heat removal','Hot-side rejection and electrical power','Startup / control stability','Working-fluid integrity where applicable'],criteria:'Approved cold-side capacity, hot-side rejection, electrical and temperature requirements are met; selected machine and working-fluid evidence remain necessary.',sources:['mat-heat-pump','v-gevs-balance']};
 const a=[review(r),activity('functional',spec.title,spec.methods||['test','analysis'],spec.setting,spec.requirement,spec.approach,spec.measure,spec.criteria+currentFunctionalTargets(r,h),{sources:spec.sources,animation:spec.animation,chart:steps(spec.setting==='thermal-vacuum'?'thermal-cycle':spec.setting==='load-frame'?'load':'sequence',['Define case','Configure / baseline','Apply stimulus','Measure / compare','Review evidence'])}),...environmental(r,{mechanical:spec.mechanical!==false,thermal:spec.thermal!==false,emc:spec.emc})];
 if(spec.animation)a.push(activity('fit-demonstration','Installed motion and interface demonstration',['demonstration','inspection'],'deployment',`${r.title} shall follow the approved integration or motion sequence without interface interference.`,
 'Inspect interfaces and demonstrate the planned sequence on an appropriately supported article. In this workbench the animation explains the intent; dimensional fit, force, latch and timing criteria require controlled hardware evidence.',
 ['Sequence and interface state','Visible clearance / access','Final configuration and latch indication where applicable'],
 'The approved sequence is completed with correct interface states and no unresolved obstruction. The browser animation is an illustration, not an executed acceptance record.',{animation:spec.animation,sources:['v-integration','v-gevs-mechanism'],chart:steps('sequence',['Initial state','Release / mate','Travel / fit','Final state'])}));
 return profile(`flight-${w}`,r.title,spec.purpose,a,{analyses:flightAnalyses(r,h),sources:['v-plan','v-methods','v-outline','v-integration',...spec.sources],level:['01.01','02.01','03.01','03.02','07.01','07.02'].includes(w)?'Assembly':'Subsystem equipment'});
}

