const detailSpecs={
 'thermal-interface':{setting:'thermal-vacuum',title:'Heat-path conductance and interface workmanship',req:'The detail shall preserve its allocated heat-transfer path without incompatible joints or hidden bond damage.',approach:'Inspect mating flatness, surface treatment, fasteners, bonds and thermal-interface application. Measure conductance on a representative interface or parent assembly with controlled heat input and boundary temperatures; correlate contact resistance.',measure:['Surface / bond condition','Applied heat and interface temperature difference','Flatness / preload and material lot'],criteria:'The approved conductance, contact, bond and dimensional requirements are met in a representative assembly. Cosmetic surface appearance does not establish thermal contact.',sources:['mat-thermal','mat-act-chassis','v-gevs-balance'],chart:'thermal-cycle'},
 'board':{setting:'electrical-bench',title:'Board workmanship and functional coverage',req:'The board assembly shall meet workmanship and electrical requirements with traceable parts and processes.',approach:'Inspect package, solder and interconnect workmanship; review parts screening and radiation strategy. Run board-level function, power and interface diagnostics, then reference parent assembly environmental coverage.',measure:['Parts / lot and assembly process record','Workmanship inspection and relevant NDE','Board diagnostics and current / temperature'],criteria:'Approved assembly criteria and board diagnostics are satisfied; screened part populations and firmware are traceable. Commercial device specifications do not establish radiation or vacuum qualification.',sources:['mat-workmanship','mat-ttm','flight-rha'],chart:'signal'},
 'housing':{setting:'fit-check',title:'Enclosure interfaces and installed thermal / electrical paths',req:'The enclosure shall retain the internal hardware and meet its allocated mechanical, thermal and grounding interfaces.',approach:'Inspect machined dimensions, finish, inserts and fasteners. Gauge mating datums, card retention and connector access; measure selected bond or heat-path properties in the populated parent assembly.',measure:['Dimensions / insert and thread condition','Fastener and retention evidence','Grounding and thermal-interface condition'],criteria:'The controlled drawing and process requirements are met with correct fit and no unintended insulating film at required bonds. Parent environmental tests supply assembly evidence.',sources:['mat-anodize','mat-act-chassis','v-gevs-mechanical'],chart:'inspection'},
 'solar-cell':{setting:'electrical-bench',title:'Cell lot and string electrical evidence',req:'The selected cells and interconnect process shall support the allocated electrical output and remain intact through the array environment.',approach:'Review the selected cell or cell-interconnect-coverglass lot, measure representative I–V output under calibrated spectrum and temperature, inspect interconnect bonds and verify string continuity. Use coupons/subassemblies for process and environmental qualification.',measure:['Corrected I–V characteristics','Interconnect resistance / bond evidence','Cell damage and lot traceability'],criteria:'The approved cell, bond and string criteria are met with correction uncertainties documented. Beginning/end-of-life performance requires the selected cell environment evidence.',sources:['mat-spectrolab','mat-sharp','mat-esa-cell'],chart:'signal'},
 'coverglass':{setting:'optical-bench',title:'Coverglass transmission and bonded-cell inspection',req:'The coverglass system shall preserve allocated cell illumination and protect the selected cell without unacceptable bond or surface defects.',approach:'Inspect thickness, chips, coating, adhesive lot and bond coverage. Review spectral transmission and environmental evidence on representative bonded-cell specimens; confirm compatibility with the cell and array process.',measure:['Spectral transmission / coating evidence','Thickness and edge condition','Adhesive / bond coverage and contamination'],criteria:'The selected glass/coating/adhesive process meets its approved transmission, defect and bond criteria. Coverglass is verified as a bonded cell system, not an independent spacecraft shaker article.',sources:['mat-esa-cell','mat-spectrolab','v-gevs-clean'],chart:'inspection'},
 'blanket-support':{setting:'deployment',title:'Flexible support and interconnect accommodation',req:'The flexible substrate shall preserve geometry, cell retention and electrical clearance through stowage and deployment.',approach:'Inspect layup and attachment processes, characterize representative flex/bend specimens and demonstrate packaging/deployment with the parent blanket. Record strain-sensitive interfaces and cell/interconnect condition.',measure:['Material / layup traceability','Fold / bend and attachment condition','Deployment clearance and electrical continuity'],criteria:'The approved bend, retention and deployment criteria are met on a representative blanket; parent electrical performance remains within limits before/after the sequence.',sources:['mat-rosa','mat-redwire','v-gevs-mechanism'],animation:'deployment'},
 'composite-boom':{setting:'deployment',title:'Composite process, stiffness and deployment',req:'The boom shall preserve its load path and deploy to the required geometry within its strain and life allocation.',approach:'Review fiber/resin/layup/cure records and NDE; correlate representative structural tests and strain-energy deployment with analysis. Use a supported parent array to verify final geometry, latch and damping behavior.',measure:['Layup / cure and defect evidence','Stiffness, strain and deployed shape','Deployment force and repeated-cycle condition'],criteria:'The approved material, defect, stiffness and deployment criteria are met with accumulated-life accounting. Mesh segmentation is not a laminate definition.',sources:['mat-structures','mat-rosa','v-gevs-mechanism'],animation:'deployment'},
 'conductor':{setting:'electrical-bench',title:'Bus conductor joints and loaded temperature',req:'The conductor and its joints shall carry allocated current with acceptable voltage drop and temperature rise while preserving isolation.',approach:'Inspect cross-section, plating, clearance and joint process. Measure resistance and loaded temperature in representative mounting, including expansion and contact boundaries; verify insulation using the approved connected/disconnected configuration.',measure:['Joint / path resistance','Loaded voltage drop and temperature','Clearance, insulation and torque records'],criteria:'The approved current, voltage-drop, thermal and isolation requirements are met for the actual joint and support configuration.',sources:['mat-busbars','flight-harness','v-gevs-function'],chart:'signal'},
 'thermal-finish':{setting:'clean-inspection',title:'Finish process and optical-property evidence',req:'The finish shall supply the allocated thermal-optical properties while remaining bonded and compatible with the substrate and environment.',approach:'Trace coating or reflector material and application process; inspect coverage, thickness/adhesion where applicable and surface damage. Measure representative witness coupons or selected lots and correlate the parent thermal model.',measure:['Solar absorptance / infrared emittance evidence','Surface coverage, defects and adhesion','Material lot, application / cure record'],criteria:'Selected finish properties and process acceptance criteria are met; parent thermal-balance evidence uses the measured properties. No coating is assigned a separate vibration test detached from its substrate.',sources:['mat-az93','mat-osr','v-gevs-clean','v-gevs-balance'],chart:'inspection'},
 'panel-skin':{setting:'load-frame',title:'Face-sheet process, bonds and load path',req:'The face sheet and bonded interfaces shall transfer allocated loads and heat without unacceptable distortion or disbond.',approach:'Review material and bond-process records; inspect dimensions, surface preparation and relevant NDE. Test representative coupons/panels and use the parent structural/thermal model to establish installed coverage.',measure:['Thickness / flatness and material identity','Bond / NDE evidence','Panel deflection, strain or conductance as allocated'],criteria:'Approved material allowables, bond defects and parent panel performance criteria are satisfied; coupon-to-flight-process equivalence is documented.',sources:['mat-act-radiator','flight-hexweb','v-gevs-mechanical'],chart:'load'},
 'sandwich-core':{setting:'clean-inspection',title:'Core, insert and bond process verification',req:'The core system shall support the face sheets and inserts without unacceptable defects or moisture / venting incompatibility.',approach:'Inspect core type, orientation, thickness and process traceability. Review representative bond/shear/compression coupon evidence and parent-panel NDE; verify inserts, vent paths and repaired areas.',measure:['Core material / orientation / density evidence','Bond / insert and defect maps','Coupon strength and process equivalence'],criteria:'The controlled drawing, process and defect criteria are met; panel strength and stiffness are closed at the representative parent level. No exposed decorative hexagon proves internal bond quality.',sources:['flight-hexweb','mat-act-radiator','v-gevs-mechanical'],chart:'inspection'},
 'fluid-component':{setting:'pressure-bench',title:'Wetted component cleanliness, flow and integrity',req:'The component shall maintain its allocated fluid boundary and flow function with compatible wetted materials.',approach:'Trace material, joints, seals and cleaning processes; inspect geometry and NDE where required. Plan applicable leak/proof/flow checks at component or integrated-circuit level, with test media and conditions approved for the selected hardware.',measure:['Material and cleaning records','Leak / pressure / flow data','Joint, weld and seal condition'],criteria:'The selected pressure-system and cleanliness limits are met; final circuit leakage is checked after stress or integration that can change integrity. No universal proof factor or test fluid is imposed.',sources:['mat-valves','flight-fluid-compatibility','v-gevs-clean'],chart:'sequence'},
 'blanket-cover':{setting:'clean-inspection',title:'Blanket-cover material and installed fit',req:'The outer cover shall preserve its allocated thermal, handling and contamination function without obstructing interfaces.',approach:'Verify actual film/cloth, coatings, seams, attachments and bonding provisions. Inspect fit on the parent blanket and retain representative coupon optical/material evidence; review storage, handling and venting.',measure:['Material / coating lot and pattern','Seam, fastener and vent condition','Surface cleanliness and optical-property evidence'],criteria:'Approved material, pattern, seam, coverage and bond requirements are met. Installed thermal performance is closed through the parent blanket and spacecraft model/test.',sources:['mat-sheldahl','mat-beta','mat-mli-optics','v-gevs-clean'],chart:'inspection'},
 'mli-stack':{setting:'clean-inspection',title:'Concealed layer and blanket assembly record',req:'The insulation stack shall preserve the allocated layer spacing, venting and thermal resistance in its installed configuration.',approach:'Inspect and document layer sequence, separators, seams and penetrations during fabrication before closure. Use process/coupon evidence and parent thermal-balance data to assess installed performance.',measure:['Layer / separator build record','Seam and penetration geometry','Blanket heat-leak / thermal-model evidence'],criteria:'The controlled blanket construction and handling requirements are met; no hidden layer count is inferred from the visible outer film.',sources:['mat-mli-optics','mat-sheldahl','v-gevs-balance'],chart:'inspection'},
 'precision-housing':{setting:'optical-bench',title:'Datum alignment and thermoelastic stability',req:'The precision structure shall retain the allocated bearing, optical or mechanism alignment under installed loads and temperatures.',approach:'Survey defined datums using calibrated metrology, inspect joints and fits, and correlate thermal/structural distortion. Verify final alignment on the populated parent after relevant environmental exposure.',measure:['Datum position / orientation','Joint and fit condition','Thermal / load-induced alignment change'],criteria:'The approved alignment and repeatability budget is satisfied, including metrology uncertainty and parent-level distortion.',sources:['mat-cmg','mat-optical-terminal','v-gevs-mechanical'],chart:'inspection'},
 'magnetic-housing':{setting:'electrical-bench',title:'Magnetic compatibility and retention',req:'The housing shall retain the actuator without unacceptable magnetic bias, attenuation or thermal restriction.',approach:'Inspect material identity and fasteners, review magnetic material/process compatibility and measure the populated actuator field and thermal behavior against its baseline.',measure:['Material and process records','Residual / driven field evidence','Retention, alignment and temperature'],criteria:'The housing drawing and installed magnetic/thermal allocation are met. A black finish does not identify the alloy or magnetic cleanliness.',sources:['mat-magnetorquer','flight-rod'],chart:'signal'},
 'winding':{setting:'electrical-bench',title:'Winding workmanship, insulation and dipole evidence',req:'The winding shall carry its allocated current with correct polarity, isolation and temperature behavior.',approach:'Trace wire and insulation lots, inspect termination and impregnation process, measure resistance and approved insulation characteristics, then correlate the parent actuator dipole and thermal response.',measure:['Resistance and continuity','Polarity and insulation integrity','Current / temperature and parent dipole'],criteria:'Approved winding and actuator criteria are met with process traceability; conductor color is not insulation or thermal evidence.',sources:['mat-magnetorquer','mat-workmanship'],chart:'signal'},
 'optical-baffle':{setting:'optical-bench',title:'Baffle geometry, finish and stray-light control',req:'The baffle shall suppress allocated stray light without obscuring the useful optical field or contaminating the optic.',approach:'Survey apertures and exclusion geometry, inspect the low-reflectance treatment and cleanliness, and correlate representative stray-light measurements with the installed optical model.',measure:['Aperture / field clearance','Surface reflectance evidence','Stray-light response and particle condition'],criteria:'The approved optical field, stray-light and cleanliness budgets are met using measured finish properties and installed geometry.',sources:['mat-hydra','mat-superblack','mat-tbird','v-gevs-clean'],chart:'signal'},
 'rf-dielectric':{setting:'rf-chamber',title:'Dielectric lot and installed antenna match',req:'The dielectric construction shall preserve the allocated antenna impedance and radiation performance.',approach:'Review selected laminate material, thickness and dielectric/loss data at the applicable band; inspect bonding and conductive geometry. Measure the completed antenna match and radiation performance after relevant exposure.',measure:['Laminate lot / thickness / dielectric evidence','Bond and pattern geometry','Antenna match and radiation data'],criteria:'The approved material and completed-antenna requirements are met. A generic dielectric material label is insufficient to establish RF performance.',sources:['mat-rf-laminate','mat-anywaves'],chart:'signal'},
 'contact-finish':{setting:'electrical-bench',title:'Contact plating and joint resistance',req:'The contact finish shall preserve allocated electrical contact through the specified mating and environmental history.',approach:'Inspect plating and substrate process records, coverage and damage; measure representative contact resistance and review wear/corrosion evidence for the selected connector or feed interface.',measure:['Plating material / thickness record','Contact resistance and coverage','Mating-cycle and environmental evidence'],criteria:'The approved finish and contact criteria are met on representative interfaces. Plating is verified as part of its substrate/contact system.',sources:['mat-contacts','mat-harness'],chart:'signal'},
 'reflector':{setting:'rf-chamber',title:'Reflector figure and RF alignment',req:'The reflector and support shall maintain the allocated surface figure and feed alignment across its installed environment.',approach:'Survey the reflector surface and datums, correlate deformation analysis and measure completed-antenna performance. Inspect support joints and repeat alignment after the relevant mechanical/thermal sequence.',measure:['Surface figure and feed alignment','Joint / support condition','Gain / pattern and polarization'],criteria:'The approved surface, alignment and antenna-performance budgets are met with uncertainty documented; mesh smoothness is not RF surface accuracy.',sources:['mat-nisar','flight-comms'],chart:'signal'},
 'optical-window':{setting:'optical-bench',title:'Optic transmission, wavefront and surface quality',req:'The optic shall preserve allocated transmission and optical quality while surviving its mounting and environment.',approach:'Review glass/coating selection and lot records, inspect surface/edge defects, measure spectral transmission and applicable wavefront quality, and verify the representative mount without introducing harmful stress.',measure:['Transmission / coating and wavefront evidence','Surface / edge and contamination inspection','Mount alignment and stress-sensitive behavior'],criteria:'The selected optic and installed optical budget are met; wavelength, wavefront and surface-quality tolerances remain explicit approved requirements.',sources:['mat-window','mat-optical-terminal','v-gevs-clean'],chart:'signal'},
 'hot-structure':{setting:'propulsion-stand',title:'Hot-section material, wall and life evidence',req:'The nozzle detail shall retain the required geometry and integrity over the approved thermal and firing history.',approach:'Trace the selected refractory or coated material, manufacturing process and wall inspection; review representative hot-fire and life evidence, then inspect the delivered engine detail under its supplier acceptance plan.',measure:['Material / process and NDE records','Wall / surface and erosion evidence','Thermal-cycle and accumulated firing history'],criteria:'Supplier-controlled material, dimensional and life criteria are met for the selected engine design. The rendered material does not select a hot-section alloy or establish a firing limit.',sources:['mat-s400','launch-nozzle','flight-engine'],chart:'sequence'},
 'pressure-shell':{setting:'pressure-bench',title:'Pressure-shell process and vessel evidence',req:'The shell and its joints shall preserve the selected vessel pressure boundary and service compatibility.',approach:'Review alloy/heat treatment, forming and weld records; inspect geometry and NDE using the pressure-system plan. Link article proof/leak records and fracture/life assessment to the complete vessel.',measure:['Material / heat / weld and NDE traceability','Thickness / geometry and joint condition','Vessel proof / leak and life evidence'],criteria:'The approved vessel design and material/process criteria are met. Shell-only appearance does not establish pressure capacity or a separate standalone test program.',sources:['mat-pmd','flight-sp8112','flight-fluid-compatibility'],chart:'sequence'},
 'composite-pressure':{setting:'pressure-bench',title:'Overwrap process and vessel-life traceability',req:'The overwrap system shall satisfy its selected vessel strength and life allocation with controlled manufacturing history.',approach:'Trace fiber/resin, winding pattern, cure, liner and NDE records. Review supplier qualification and stress-rupture/fatigue assessment, and connect delivered article proof/leak acceptance to the vessel serial record.',measure:['Winding / cure / material records','Liner / overwrap and NDE condition','Pressure / temperature / time history'],criteria:'The selected vessel authority closes strength, life and article acceptance requirements; no generic composite density, visual weave or assumed factor is used as pressure qualification.',sources:['mat-copv','flight-copv-life','mat-pressurant'],chart:'sequence'},
 'load-path':{setting:'load-frame',title:'Structural detail, joint and load-path evidence',req:'The detail and its joints shall carry their allocated interface loads without unacceptable stress, instability or permanent distortion.',approach:'Inspect controlled material, section, holes, threads and fastener process; correlate applicable coupon/joint/assembly testing with the structural model. Verify fit and the installed preload/load path before release.',measure:['Material / process and dimensional evidence','Joint preload / NDE','Load, strain and displacement evidence'],criteria:'Approved strength, buckling, fatigue and dimensional requirements are met at the proper structural level with the actual interfaces represented.',sources:['mat-structures','v-gevs-mechanical','mat-lightband'],chart:'load'},
 'feedthrough':{setting:'fit-check',title:'Feedthrough boundary definition and integrity',req:'The selected feedthrough shall preserve its required isolation, sealing and mechanical interface without incompatible materials.',approach:'First define whether the penetrated boundary is electrical, fluid, optical or simply structural. Select the insulator/seal and then inspect fit, material compatibility and applicable continuity, isolation or leakage evidence on the assembled interface.',measure:['Resolved boundary and selected material','Fit / compression / connector condition','Applicable electrical or leak measurements'],criteria:'The approved boundary-specific requirements are met. The catalog currently marks this material unresolved; no seal pressure rating or dielectric strength is inferred.',sources:['mat-feedthrough','v-gevs-clean','v-gevs-function'],chart:'inspection'},
 'shield':{setting:'review',title:'Shield material and as-built coverage assessment',req:'The installed shielding shall match the geometry and material used in the approved radiation assessment.',approach:'Verify actual material, density/thickness evidence, penetrations, overlaps and placement. Update the radiation transport model from the controlled installed configuration and review selected-device tolerances.',measure:['Material / areal density evidence','As-built coverage and gaps','Dose / particle transport assessment'],criteria:'Installed configuration is traceable to the approved radiation assessment; no shielding effectiveness is inferred from a metallic appearance.',sources:['mat-radiation','mat-juno','flight-rha'],methods:['analysis','inspection'],chart:'inspection'},
 'mechanism-detail':{setting:'deployment',title:'Mechanism joints, lubrication and motion evidence',req:'The detail shall preserve its allocated clearances and force / torque contribution through the parent mechanism life.',approach:'Inspect bearing/hinge/gear fits, lubricant and process records, torque/preload and locks. Demonstrate motion in the parent mechanism and use representative life / thermal evidence to bound friction, wear and final alignment.',measure:['Fits, preload and process records','Torque / force versus travel','Wear, latch and end-stop condition'],criteria:'The approved mechanism-detail and end-of-life margin criteria are met at the assembled mechanism level; replaying the browser motion does not supply those measurements.',sources:['mat-sada','v-gevs-mechanism'],animation:'deployment'},
 'harness-cover':{setting:'electrical-bench',title:'Insulation workmanship and routed protection',req:'The cover and insulation shall preserve electrical isolation and mechanical protection over the installed routing and motion.',approach:'Trace selected wire/insulation/braid, inspect damage, bend and strain-relief provisions, and verify approved electrical isolation on the finished harness. Assess thermal and environmental compatibility with the actual wire construction.',measure:['Material / workmanship record','Abrasion / bend / support condition','Finished-harness isolation and continuity'],criteria:'The approved harness drawing, workmanship and isolation requirements are met without damaged insulation or unprotected chafe paths.',sources:['mat-harness','mat-workmanship','v-gevs-function'],chart:'inspection'},
};

function detailProfile(r,c,h){
 const assignment=detailAssignments[r.wbs||r.id.slice(7)];if(!assignment)return null;
 let [kind,context]=assignment;
 if(r.id==='flight:03.02.01'&&h.energySystem?.thermal?.kind==='passive-local'){kind='thermal-interface';context='the selected passive heat-pipe / strap / spreader path';}
 const d=detailSpecs[kind],parent=get(c,r.parentId),parentName=parent?.title||r.parentId;
 const boundary='The verification article is a process witness coupon, selected procurement lot, representative subassembly or the populated parent as specified by the approved procedure. This rendered detail has no separate MEL mass allocation.';
 const check=activity('detail-characterization',d.title,d.methods||['inspection','test','analysis'],d.setting,d.req,`${d.approach} For this item, focus on ${context}.`,d.measure,d.criteria,{article:'engineering',conditions:boundary,sources:d.sources,animation:d.animation,chart:{...steps(d.chart||'sequence',['Trace material / process','Inspect detail','Characterize representative article','Confirm parent coverage']),articleLabel:'Witness coupon / representative assembly'}});
 const parentCheck=activity('installed-evidence','Installed interface and parent evidence',['inspection','analysis'],'installed',`${r.title} shall be installed in the configuration represented by the ${parentName} verification evidence.`,
 `Review the detail-to-parent drawing and process traveler, inspect ${context}, and trace applicable thermal, mechanical, electrical or environmental evidence to ${parentName}. Check changes, repairs and deviations before using earlier evidence.`,
 ['Detail-to-parent configuration match','Interface and process traceability','Applicability of parent evidence'],
 'The detail matches the approved installed configuration, and every relied-on parent or supplier result identifies an applicable article and process. Gaps remain open until reviewed; no qualification is inherited solely from a catalog name.',{article:'installed',sources:['v-integration','v-gevs-plan'],conditions:boundary,chart:{...steps('inspection',['Detail record','Parent interface','Applicable evidence','Handover']),articleLabel:parentName}});
 const p=profile(`detail-${kind}`,r.title,`Verification concentrates on ${context}, then follows the installed interfaces into ${parentName}.`,[check,parentCheck],{level:'Material / detail',scope:boundary,defaultSetting:['shield'].includes(kind)?'installed':'review',sources:['v-plan','v-methods','v-outline','v-integration',...d.sources]});
 if(['thermal-finish','coverglass','rf-dielectric','blanket-cover'].includes(kind))p.activities.push(activity('coupon-cycling','Representative material / bond thermal cycling',['test','inspection'],'thermal-cycle',
  'The selected material, finish or bonded system shall retain its allocated properties through the approved thermal exposure.',
  'Prepare traceable witness specimens with the actual substrate, preparation, application and cure or bonding process. Inspect and measure the properties relevant to this detail before and after the approved cycling screen; assess whether separate vacuum or mission-environment evidence is also required.',
  ['Specimen-to-flight process equivalence','Specimen temperature and controlled cycle history','Adhesion / bond / damage observations','Relevant optical or electrical property change'],
  'The approved specimen temperatures, cycle history, defect and property-change limits are met. An atmospheric material screen does not substitute for assembled thermal-vacuum performance or flight qualification.',
  {article:'engineering',conditions:'A representative coupon or bonded specimen is the article; the depicted full-size part provides context only. Cycle limits, humidity control and test medium require the material/process authority’s approval.',sources:['v-gevs-clean','v-gevs-tvac'],chart:{...steps('thermal-cycle',['Baseline properties','Approved hot / cold cycles','Inspect bonds / surface','Re-measure properties']),articleLabel:'Representative material / bond coupon'}}));
 const allocation=parent?.extendedMassKg;
 if(finite(allocation))p.analyses.push(fieldAnalysis('detail-parent-allocation','Parent allocation and evidence boundary','interfaces','The selected detail is a subset of a parent allocation. The test article must represent the actual detail and interfaces used by that parent.',[datum('Parent mass allocation',allocation,'kg'),datum('Detail role',context),datum('Model material',r.materialId||'Unresolved')],[datum('Added mass from this detail',0,'kg','Non-additive detail; included in the parent MEL allocation.'),datum('Independent detail acceptance limits','To be allocated on the selected drawing / process')],['The zero added mass is an accounting rule; the physical detail is not massless.','Mesh dimensions and procedural finishes are not a manufacturing drawing or material certificate.'],['v-plan','v-integration']));
 return p;
}

