function mateActivity(r,{article='flight',sources=['v-integration','v-gevs-function']}={}){
 return activity('mate','Fit, mate and interface demonstration',['inspection','demonstration'],'fit-check',`${r.title} shall fit its approved receiving interfaces and remain accessible for the required integration checks.`,
 'Inspect both mating sides, their datums, alignment/keying, fasteners, connectors and required access. Demonstrate the controlled installation/removal sequence with a suitable article or surrogate. The 3D translation shows the intended path and final context.',
 ['Mating datum / orientation and connector identity','Nominal clearance and tool access','Retention and final interface state'],
 'The approved interface drawing and installation sequence are satisfied with discrepancies dispositioned. Nominal 3D motion supplies no tolerance, contact-force or as-built fit certification.',{article,sources,animation:'mate',chart:steps('sequence',['Inspect both sides','Align / approach','Mate / retain','Verify interface'])});
}
function groundProfile(r,c,h){
 const key=r.id.slice(7),s=groundSpecs[key];if(!s)return null;
 const permanent=['facility','bridge-crane','propellant-loading'].includes(key);
 const scope='Ground equipment is verified as enabling hardware or software under the facility/project requirements. Calibration and commissioning qualify its use in a test; they do not qualify the spacecraft or impose flight GEVS environments on this equipment.';
 const receive={...review(r),setting:permanent?'installed':'clean-inspection',article:'installed',sources:['ground-gse','v-methods'],conditions:'Receiving records refer to this ground item, its rated configuration and applicable facility authority.'};
 const run=activity('commissioning',s.title,['inspection','test','analysis'],s.setting,s.req,s.approach,s.measure,s.criteria,{article:'installed',conditions:'Use the governing ground-equipment/facility specifications and approved commissioning procedure. Flight environmental test levels are not automatically applicable.',sources:s.sources,animation:s.animation,chart:{...steps(s.kind==='metrology'?'inspection':s.kind==='electrical'||s.kind==='rf'||s.kind==='software'?'signal':s.kind==='lifting'||s.kind==='support'?'load':'sequence',['Define supported range','Calibrate / inspect','Exercise reference cases','Review commissioning']),articleLabel:'Ground equipment / reference load'}});
 const readiness=activity('readiness','Calibration, maintenance and use readiness',['inspection','demonstration'],permanent?'site-commissioning':'review',`${r.title} shall be in a known, suitable configuration before each authorized use.`,
 'Review due calibration/inspection/maintenance, software and procedure revisions, equipment identity and the supported article ICD. Demonstrate the selected pre-use reference check and record readiness or open work.',
 ['Calibration / inspection due status','Configuration and procedure match','Reference-check observations and service history'],
 'The approved pre-use checks are complete, equipment limits cover the test case and every overdue item or discrepancy has an authorized disposition.',{article:'installed',sources:['ground-gse','v-integration'],conditions:scope,chart:steps('inspection',['Identify equipment','Review status','Reference check','Authorize use'])});
 const activities=[receive,run,readiness];if(s.animation==='mate')activities.push(mateActivity(r,{article:'installed',sources:['ground-gse','v-integration']}));
 const p=profile(`ground-${s.kind}-${key}`,r.title,s.purpose,activities,{level:['facility','fluid-facility'].includes(s.kind)?'Ground facility':s.kind==='software'?'Ground software / test system':'Ground support equipment',scope,defaultSetting:permanent?'installed':'review',...(permanent?{settings:['installed','site-commissioning','studio']}:{}),sources:['v-plan','v-methods','v-outline','v-integration','ground-gse',...s.sources]});
 const target=s.target&&get(c,'flight:'+s.target);
 p.analyses.push(fieldAnalysis('gse-coverage','Ground-equipment capability allocation','interfaces','Start with the supported interface, then allocate equipment range, stimulus fidelity and measurement uncertainty before selecting a specific unit.',[datum('Ground item',r.title),datum('Supported product',target?.title||fact(r,'Task')||'Facility / campaign requirement'),...(finite(target?.extendedMassKg)?[datum('Supported allocation mass',target.extendedMassKg,'kg')]:[])],[datum('Equipment rated range','Not selected / not certified by this model'),datum('Measurement uncertainty allocation','To be derived from the verified requirement')],['A supported flight mass or power value does not certify ground-equipment capacity.','The scene is schematic; supplier model, calibration and commissioned facility records remain open.'],['ground-gse','v-methods']));
 if(target){const live=flightAnalyses(target,h).slice(0,1);for(const a of live)p.analyses.push({...a,id:'supported-'+a.id,title:'Supported article: '+a.title,description:'These are the flight article’s current design inputs used to plan equipment capacity; they are not ground-equipment ratings. '+a.description});}
 return p;
}

