function providerSource(h){const id=h.input?.launcher||'';return id.startsWith('terran')?'launch-terran':id.startsWith('glenn')?'launch-newglenn':id==='starship'?'launch-starship':id==='falconHeavy'?'launch-falcon':id.startsWith('vulcan')?'launch-vulcan':id.startsWith('ariane')?'launch-ariane-guide':id==='longMarch9'?'launch-longmarch9':'launch-longmarch';}
function launchProfile(r,c,h){
 const key=r.id.slice(7),booster=/^booster-\d+$/.test(key),s=booster?{...launchSpecs.core,level:'Booster assembly',purpose:'Trace the selected side booster, attachment and separation interfaces through provider verification.',title:'Side-booster loads, propulsion and separation evidence',req:'The selected booster shall meet provider-approved propulsion, load and separation requirements.',approach:'Review the selected booster and attachment configuration, structural/propulsion evidence and separation analysis/test coverage; trace coupled interfaces and article acceptance into the integrated launch vehicle.'}:launchSpecs[key];
 if(!s)return null;
 const sources=unique([...s.sources,providerSource(h)]),scope='The launch provider owns the vehicle qualification and article acceptance program. This page proposes evidence and interface questions for a mission PDR; it does not state that the provider performs any particular unpublished test or disclose certified limits.';
 const record=activity('provider-record','Provider configuration and applicable evidence',['inspection','analysis'],'review',`${r.title} shall be tied to the agreed vehicle and mission configuration.`,
 'Identify the selected provider revision, article/configuration and supplied verification deliverables. Separate public architecture references from controlled qualification, acceptance and mission-interface evidence; assess changes and open data requests.',
 ['Provider / configuration identity','Evidence applicability and revision','Mission-specific interface and open-item list'],
 'The required provider evidence is identified and accepted by the responsible authorities; missing or proprietary evidence remains open rather than assumed from a public source.',{article:'provider',conditions:scope,sources,chart:steps('inspection',['Public reference','Controlled configuration','Required deliverables','Authority review'])});
 const plan=activity('provider-verification',s.title,['analysis','test','inspection'],s.setting,s.req,s.approach,s.measure,s.criteria,{article:'provider',conditions:scope,sources,animation:s.animation,chart:{...steps(s.setting==='propulsion-stand'?'sequence':s.setting==='load-frame'?'load':'sequence',['Define provider scope','Review / perform applicable verification','Correlate interfaces','Close mission evidence']),articleLabel:'Provider-selected article'}});
 const activities=[record,plan];
 if(s.animation==='mate')activities.push(mateActivity(r,{article:'provider',sources:['v-integration',providerSource(h)]}));
 else if(s.animation)activities.push(activity('provider-sequence','Nominal interface sequence',['demonstration'],'deployment',`The approved ${r.title} sequence shall reach its required end state with compatible interfaces.`,
 'Use the visualization to inspect the intended sequence and required end states, then identify the physical demonstration and provider evidence needed to verify clearance, forces, timing and release.',
 ['Initial / final interface states','Nominal travel and access','Provider motion and clearance evidence'],
 'The provider-approved sequence and physical evidence meet the allocated criteria. The workbench replay is explanatory only.',{article:'provider',conditions:scope,sources,animation:s.animation,chart:steps('sequence',['Initial state','Release / travel','Clear interfaces','Final state'])}));
 const p=profile(`launch-${booster?'booster':key}`,r.title,s.purpose,activities,{level:s.level,scope,defaultSetting:'review',sources:['v-plan','v-methods','v-outline','v-integration',...sources]});
 p.analyses.push(fieldAnalysis('launch-evidence-boundary','Selected configuration and evidence boundary','interfaces','This record follows the active launcher configuration. Public recognition geometry is not a provider structural, propulsion or flight-readiness model.',[datum('Selected launcher',h.launcherLabel||get(c,'launch:vehicle')?.title||'Unallocated'),datum('Provider',fact(get(c,'launch:vehicle')||{},'Provider')||'See selected reference'),...r.facts.filter(f=>typeof f.value==='number').slice(0,4).map(f=>datum(f.label,f.value,f.unit||''))],[datum('Verification owner','Launch provider / agreed customer interface'),datum('Article test result','Not supplied in this workbench')],['Use the contracted ICD and applicable provider configuration; the plan does not select unpublished test levels.','Spacecraft MEL totals exclude launch vehicle hardware.'],sources));
 return p;
}

