 p.analyses.push(fieldAnalysis('site-boundary','Architecture and commissioning boundary','interfaces','Use the actual catalog evidence status and current launcher/site selection to identify what remains a design assumption.',[datum('Selected site item',r.title),datum('Catalog evidence',fact(r,'Evidence')||'See the site/source basis'),datum('Current launcher',h.launcherLabel||'Selected configuration')],[datum('Survey / certified capacity','Not supplied by this schematic'),datum('Commissioning result','No result entered')],['Provider facility records and the governing codes/specifications define acceptance limits.','No civil mass, pressure rating, inventory or separation distance is calculated from scene geometry.'],s.sources));
