 const p=profile(`umbilical-${flight?'flight':'ground'}`,r.title,'A coordinated interface plan combines individual circuit evidence with support, mating and release behavior.',a,{level:'Umbilical assembly',scope,sources:['v-plan','v-methods','v-outline','v-integration','ground-letf','ground-umbilicals']});
