// Harnesses, mating pairs and avionics cards share the controlled electrical
// baseline. Their verification page must retain that allocation, not fall back
// to a generic material coupon or a receiving-inspection blurb.
function electricalProfile(r,c,h){
 const definition=r.electricalDefinition;
 if(!definition||definition.kind==='equipment'||!h?.input)return null;
 const program=buildElectricalProgram(h),item=electricalProgramForItem(program,r.id);
 if(!item)return null;
 const ground=r.category==='ground',article=ground?'installed':'flight';
 const label=k=>k.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/([A-Z]+)([A-Z][a-z])/g,'$1 $2');
 const value=v=>Array.isArray(v)?v.join(', '):v&&typeof v==='object'?JSON.stringify(v):typeof v==='boolean'?(v?'Required':'Not permitted'):typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('en-US',{maximumSignificantDigits:6}):String(v);
 const criteria=item.requirements.map(q=>q.id+': '+Object.entries(q.criteria).map(([k,v])=>label(k)+' = '+value(v)).join('; ')).join('. ');
 const sourceIds=unique(item.requirements.flatMap(q=>q.sourceIds)).filter(id=>verificationSources[id]);
 const activities=[{...review(r),article,sources:unique(['v-methods','el-nasa-workmanship',...sourceIds])}];
 for(const plan of item.plans){
  const analysis=plan.executionMode==='numerical-prediction'||plan.methods.length===1&&plan.methods[0]==='analysis'||plan.id.endsWith(':analysis');
  activities.push(activity('electrical-'+(analysis?'analysis':'checkout'),plan.title,plan.methods,'electrical-bench',
   item.requirements.map(q=>q.statement).join(' '),plan.steps.join(' '),
   analysis?['Endpoint and net-map completeness','Wire/contact compatibility, allocated current and supply/return voltage drop','Physical signaling rate, route length and bend allowance','Configuration ID and predicted shortfalls']:['Point-to-point continuity or optical polarity','Isolation and shell/bond measurements at approved test conditions','Loaded power, command/status and data integrity','Functional behavior at allocated supply and temperature corners'],
   criteria,{article,sources:unique([...sourceIds,'v-gevs-function','v-integration']),requirementIds:plan.requirementIds,planId:plan.id,evidence:plan.evidenceRequired,conditions:ground?'Use the controlled ground adapter, isolation and safe-to-mate procedure. This removable lead is not flight hardware.':'Use the current released interface baseline, representative mating equipment and the article-specific thermal allocations. The browser prediction does not close physical acceptance.',...(analysis?{}:{animation:'electrical'}),chart:steps('signal',analysis?['Resolve interfaces','Calculate margins','Record shortfalls','Retain prediction']:['Isolate / inspect','Measure nets / bonds','Mate / power','Exercise signals','Retain measurements'])}));
 }
 activities.push(mateActivity(r,{article,sources:['el-nasa-workmanship','v-integration','v-gevs-function']}));
 if(!ground){
  const environment=environmental(r,{mechanical:true,thermal:true,emc:definition.kind==='card'||definition.kind==='antenna'});
  for(const a of environment)if(a.id==='thermal-environment'){
   a.criteria='Use the article temperatures, chamber boundaries, dwell and stability allocations in this part’s thermal engineering plan. All applicable electrical functions remain within the interface criteria at the allocated voltage/temperature corners; resolve unexplained pre/post changes before acceptance.';
   a.conditions='The numerical thermal model and allocated test schedule are linked to this article and configuration. Qualification versus recurring acceptance tailoring, approved procedures and measured evidence remain separate.';
  }
  activities.push(...environment);
 }
 const p=profile('electrical-'+definition.kind,r.title,ground?'Verify the removable checkout lead and its isolated flight-interface adapter before integration use.':'Verify the actual electrical interfaces, build definition and functional allocation before integrating this item into its parent.',activities,{level:ground?'Electrical ground support':definition.kind==='harness'?'Harness assembly':definition.kind==='connector'?'Mating connector pair':definition.kind==='antenna'?'RF antenna':'Avionics card',defaultSetting:'review',sources:['v-plan','v-methods','v-integration',...sourceIds]});
 p.analyses.push(fieldAnalysis('electrical-baseline','Electrical allocation and evidence boundary','interfaces','The same configuration-owned requirements drive the build register, diagrams, part page and executable interface checks.',
  [datum('Configuration',program.configurationId),datum('Interface revision',program.revision),datum('Allocated requirements',item.requirements.length),datum('Related harness routes',item.harnesses.length)],
  item.requirements.map(q=>datum(q.title,Object.entries(q.criteria).map(([k,v])=>label(k)+' = '+value(v)).join('; '),'',q.basis)),
  ['Use Run interface checks in Electrical interfaces & capabilities to retain the numerical prediction.','Supplier application approval, released procurement drawings and physical acceptance evidence remain open until reviewed.'],sourceIds));
 return p;
}

function resolveProfile(r,c,h){
 const electrical=electricalProfile(r,c,h);if(electrical)return electrical;
 if(/^(site|launch):connection-/.test(r.id))return connectionProfile(r,c,h);
 if(/^(site|launch):umbilical-/.test(r.id))return umbilicalProfile(r,c,h);
 if(r.id.startsWith('site:commodity-')&&r.id!=='site:commodity-services')return commodityProfile(r,c,h);
 if(r.category==='site'){const p=siteProfile(r,c,h);if(p)return p;}
 if(r.category==='launch'){const p=launchProfile(r,c,h);if(p)return p;}
 if(r.category==='ground'){const p=groundProfile(r,c,h);if(p)return p;}
 if(r.category==='flight'&&r.parentId){const p=detailProfile(r,c,h);if(p)return p;}
 if(r.category==='flight'&&!r.parentId){const p=flightProfile(r,c,h);if(p)return p;}
 return profile('receiving-review',r.title,'Establish identity, interface readiness and the evidence needed for the next integration step.',[review(r)],{level:r.category==='site'?'Site infrastructure':r.category==='ground'?'Ground support equipment':'Assembly'});
}

export function partVerification(record,catalog,hardware={}){
 if(!record)return null;
 const p=resolveProfile(record,catalog,hardware);
 const joinableFlight=record.category==='flight'&&!record.parentId&&!['06.06','06.07','06.08','03.03','07.03'].includes(record.wbs||record.id.slice(7));
 const joinableDetail=record.category==='flight'&&record.parentId&&['housing','precision-housing','magnetic-housing','load-path','mechanism-detail','reflector','optical-baffle','pressure-shell'].includes(detailAssignments[record.wbs||record.id.slice(7)]?.[0]);
 if((joinableFlight||joinableDetail)&&!record.render?.unavailable&&!record.render?.contextOnly&&!p.activities.some(a=>a.animation==='mate'))p.activities.push(mateActivity(record));
 const supported=new Set((record.animations||[]).map(a=>a.id));
 if(supported.has('electrical')&&!p.activities.some(a=>a.animation==='electrical')&&hardware?.input){
  const item=electricalProgramForItem(buildElectricalProgram(hardware),record.id),plan=item?.plans.find(q=>q.executionMode==='controlled-hardware-procedure');
  if(plan)p.activities.push(activity('electrical-checkout','Connected equipment interface checkout',plan.methods,'electrical-bench',
   'The connected assembly shall preserve its allocated power, command and data interfaces in the controlled integration configuration.',plan.steps.join(' '),
   ['Released endpoint and pin/net identity','Continuity, isolation and bonds before powered mating','Loaded voltage and applicable command/data performance','Functional logs at allocated voltage/temperature corners'],
   'Meet the numerical criteria in this item’s Electrical interfaces & capabilities section and retain the measured records required by the linked checkout plan.',
   {sources:plan.sourceIds.filter(id=>verificationSources[id]),requirementIds:plan.requirementIds,planId:plan.id,evidence:plan.evidenceRequired,animation:'electrical',conditions:'The animation rehearses the selected interface. Numerical checks retain predicted status; article acceptance requires actual measurements and disposition.',chart:steps('signal',['Inspect / isolate','Measure nets','Mate / power','Exercise functions','Review evidence'])}));
 }
 for(const a of p.activities)if(a.animation&&(record.render?.unavailable||(a.animation!=='mate'&&!supported.has(a.animation)))){
  const parent=get(catalog,record.parentId);
  if(parent?.animations?.some(x=>x.id===a.animation))a.approach+=` The linked parent, ${parent.title}, carries the modeled motion; review that assembly for the animated sequence.`;
  delete a.animation;
 }
 p.analyses=[...baseAnalyses(record,catalog,hardware),...(p.analyses||[])];
 p.integration=p.integration||integrationFor(record,catalog);
 p.sources=unique([...(p.sources||[]),...p.activities.flatMap(a=>a.sources||[]),...p.analyses.flatMap(a=>a.sources||[])]).filter(id=>verificationSources[id]);
 p.settings=unique([...p.settings,...p.activities.map(a=>a.setting)]).filter(id=>verificationSettings[id]);
 return p;
}
